/* src/styles/heroes.css */
.page-hero {
  --t1: #ff3d5a;
  --t2: #3d5afe;
  --t3: #f7931e;
  position: relative;
  overflow: hidden;
  padding: clamp(36px, 6vw, 72px) 0 clamp(48px, 7vw, 88px);
}
.ph-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    linear-gradient(
      180deg,
      transparent 70%,
      var(--bg)),
    radial-gradient(
      circle at 1px 1px,
      rgba(15, 23, 42, .07) 1px,
      transparent 0) 0 0 / 26px 26px;
}
.ph-bg i {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: .32;
  animation: blob 16s ease-in-out infinite;
}
.ph-bg i:nth-child(1) {
  width: 460px;
  height: 460px;
  background: var(--t1);
  top: -160px;
  right: 4%;
}
.ph-bg i:nth-child(2) {
  width: 380px;
  height: 380px;
  background: var(--t2);
  bottom: -120px;
  left: -100px;
  animation-duration: 20s;
  animation-direction: reverse;
}
.ph-bg i:nth-child(3) {
  width: 260px;
  height: 260px;
  background: var(--t3);
  top: 30%;
  left: 40%;
  animation-duration: 13s;
  opacity: .22;
}
.ph-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(24px, 4vw, 56px);
  align-items: center;
}
.ph-copy {
  min-width: 0;
}
.ph-lead {
  font-size: clamp(1.02rem, 1.4vw, 1.16rem);
  color: var(--text);
  max-width: 60ch;
  margin: 18px 0 26px;
}
.ph-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 22px;
}
.ph-badges {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 22px;
}
.ph-badges li {
  font-size: .82rem;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: 999px;
  background: #fff;
  border: 1px solid var(--line);
  color: var(--ink);
  box-shadow: var(--shadow-sm);
}
.ph-badges li::before {
  content: "\2713";
  color: var(--green);
  margin-right: 6px;
  font-weight: 800;
}
.ph-art {
  min-width: 0;
  display: flex;
  justify-content: center;
}
@media (max-width: 960px) {
  .ph-inner {
    grid-template-columns: 1fr;
  }
  .ph-art {
    order: -1;
    max-width: 420px;
    margin: 0 auto;
    width: 100%;
  }
}
@media (max-width: 640px) {
  .ph-art {
    max-width: 330px;
  }
}
.theme-home {
  --t1: #ff3d5a;
  --t2: #3d5afe;
  --t3: #f7931e;
}
.theme-pro {
  --t1: #3d5afe;
  --t2: #14b8a6;
  --t3: #6366f1;
}
.theme-about {
  --t1: #e8344e;
  --t2: #8b5cf6;
  --t3: #f59e0b;
}
.theme-earn {
  --t1: #8b5cf6;
  --t2: #f97316;
  --t3: #ec4899;
}
.theme-journey {
  --t1: #14b8a6;
  --t2: #3d5afe;
  --t3: #22c55e;
}
.theme-vault {
  --t1: #f59e0b;
  --t2: #7c3aed;
  --t3: #facc15;
}
.theme-shield {
  --t1: #10b981;
  --t2: #0ea5e9;
  --t3: #3d5afe;
}
.theme-stack {
  --t1: #f97316;
  --t2: #e8344e;
  --t3: #1e5bff;
}
.theme-stars {
  --t1: #f59e0b;
  --t2: #ec4899;
  --t3: #facc15;
}
.theme-bubbles {
  --t1: #8b5cf6;
  --t2: #14b8a6;
  --t3: #3d5afe;
}
.theme-signal {
  --t1: #22c55e;
  --t2: #3d5afe;
  --t3: #e8344e;
}
.theme-legal {
  --t1: #3d5afe;
  --t2: #94a3b8;
  --t3: #14b8a6;
}
.hero-title {
  margin: 0;
}
.hero-title .hw {
  display: inline-block;
  opacity: 0;
  transform: translateY(0.5em) rotate(2deg);
  animation: word-in .8s var(--ease) forwards;
  animation-delay: calc(var(--w) * 70ms + 80ms);
}
@keyframes word-in {
  to {
    opacity: 1;
    transform: none;
  }
}
.hl-grad .hw {
  background: var(--grad-brand);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  padding-bottom: .06em;
}
.theme-pro .hl-grad .hw,
.theme-journey .hl-grad .hw,
.theme-shield .hl-grad .hw {
  background-image:
    linear-gradient(
      120deg,
      #3d5afe,
      #14b8a6);
}
.hl-marker {
  position: relative;
  white-space: nowrap;
}
.hl-marker::after {
  content: "";
  position: absolute;
  left: -2px;
  right: -2px;
  bottom: .06em;
  height: .34em;
  background:
    linear-gradient(
      90deg,
      #fde047,
      #fbbf24);
  border-radius: 4px;
  z-index: -1;
  transform: scaleX(0);
  transform-origin: left;
  animation: marker 0.9s var(--ease) .9s forwards;
}
@keyframes marker {
  to {
    transform: scaleX(1);
  }
}
.hl-marker {
  z-index: 0;
  isolation: isolate;
}
.hl-warm .hw {
  background:
    linear-gradient(
      120deg,
      #f59e0b,
      #e8344e);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hl-mint .hw {
  background:
    linear-gradient(
      120deg,
      #10b981,
      #0ea5e9);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hl-outline .hw {
  color: transparent;
  -webkit-text-stroke: 1.5px var(--ink);
}
@media (max-width: 420px) {
  .hero-switch button {
    padding: 8px 10px;
    font-size: .78rem;
  }
}
.art {
  position: relative;
  width: min(100%, 520px);
  aspect-ratio: 1;
  margin: 0 auto;
  container-type: inline-size;
}
.art .persona {
  filter: drop-shadow(0 10px 18px rgba(15, 23, 42, .18));
}
@keyframes bob {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}
@keyframes orbit-rot {
  to {
    transform: rotate(360deg);
  }
}
@keyframes counter-rot {
  to {
    transform: rotate(-360deg);
  }
}
@keyframes pop-in {
  from {
    opacity: 0;
    transform: scale(.4);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
.ac-phone {
  position: absolute;
  left: 8%;
  top: 12%;
  width: 42%;
  aspect-ratio: 9 / 17;
  border-radius: 30px;
  background: var(--navy);
  padding: 10px;
  box-shadow: var(--shadow-lg);
  transform: rotate(-6deg);
  animation: bob 6s ease-in-out infinite;
}
.ac-screen {
  height: 100%;
  border-radius: 22px;
  background:
    linear-gradient(
      180deg,
      #fff,
      #f1f5ff);
  padding: 18px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: hidden;
}
.ac-q {
  font-family: var(--font-head);
  font-weight: 700;
  color: var(--ink);
  font-size: clamp(.7rem, 1.6vw, .92rem);
  line-height: 1.25;
  margin-bottom: 6px;
}
.ac-opt {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: clamp(.62rem, 1.4vw, .8rem);
  padding: 8px 10px;
  border-radius: 10px;
  background: #fff;
  border: 1.5px solid var(--line);
  color: var(--ink);
  font-weight: 600;
}
.ac-opt i {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid #cbd5e1;
  flex: none;
}
.ac-opt.o2 {
  animation: opt-pick 6s ease-in-out infinite;
}
.ac-opt.o2 i {
  animation: opt-dot 6s ease-in-out infinite;
}
@keyframes opt-pick {
  0%, 20% {
    border-color: var(--line);
    background: #fff;
  }
  30%, 85% {
    border-color: var(--blue);
    background: #eef2ff;
  }
  100% {
    border-color: var(--line);
  }
}
@keyframes opt-dot {
  0%, 20% {
    background: transparent;
    border-color: #cbd5e1;
  }
  30%, 85% {
    background: var(--blue);
    border-color: var(--blue);
    box-shadow: inset 0 0 0 2px #fff;
  }
}
.ac-done {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 6px;
  justify-content: center;
  font-size: clamp(.6rem, 1.3vw, .78rem);
  font-weight: 700;
  color: #fff;
  background: var(--green);
  padding: 8px;
  border-radius: 10px;
  opacity: 0;
  animation: done-in 6s ease-in-out infinite;
}
@keyframes done-in {
  0%, 40% {
    opacity: 0;
    transform: translateY(8px);
  }
  48%, 88% {
    opacity: 1;
    transform: none;
  }
  100% {
    opacity: 0;
  }
}
.ac-coins {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.ac-coin {
  position: absolute;
  left: 40%;
  top: 50%;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: .72rem;
  color: #7c4a00;
  background:
    radial-gradient(
      circle at 35% 30%,
      #fff7c2,
      #facc15 50%,
      #d97706);
  box-shadow: 0 4px 10px rgba(217, 119, 6, .4);
  opacity: 0;
  animation: coin-arc 6s cubic-bezier(.45, 0, .55, 1) infinite;
  animation-delay: calc(2.6s + var(--i) * .22s);
}
@keyframes coin-arc {
  0% {
    opacity: 0;
    transform: translate(0, 0) scale(.5);
  }
  8% {
    opacity: 1;
  }
  30% {
    transform: translate(90px, -120px) scale(1) rotate(180deg);
  }
  55% {
    opacity: 1;
    transform: translate(170px, 30px) scale(.8) rotate(360deg);
  }
  60%, 100% {
    opacity: 0;
    transform: translate(170px, 40px) scale(.5);
  }
}
.ac-jar {
  position: absolute;
  right: 8%;
  bottom: 14%;
  width: 30%;
  aspect-ratio: 4 / 5;
  border-radius: 20px 20px 28px 28px;
  background: rgba(255, 255, 255, .6);
  border: 3px solid rgba(255, 255, 255, .95);
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, .08), var(--shadow);
  overflow: hidden;
  backdrop-filter: blur(6px);
}
.ac-jar::before {
  content: "";
  position: absolute;
  left: -3px;
  right: -3px;
  top: -3px;
  height: 14px;
  background: var(--navy);
  border-radius: 12px 12px 4px 4px;
  z-index: 2;
}
.ac-fill {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 30%;
  background:
    linear-gradient(
      180deg,
      #fde047,
      #f59e0b);
  animation: jar-fill 6s ease-in-out infinite;
}
@keyframes jar-fill {
  0%, 40% {
    height: 28%;
  }
  65%, 90% {
    height: 72%;
  }
  100% {
    height: 28%;
  }
}
.ac-wave {
  position: absolute;
  left: -50%;
  top: -10px;
  width: 200%;
  height: 20px;
  background:
    radial-gradient(
      circle at 10px -4px,
      transparent 12px,
      #fde047 13px) 0 0 / 20px 20px repeat-x;
  animation: wave 2s linear infinite;
}
@keyframes wave {
  to {
    transform: translateX(20px);
  }
}
.ac-jar-label {
  position: absolute;
  left: 50%;
  top: 42%;
  transform: translateX(-50%);
  font-weight: 800;
  font-size: clamp(.6rem, 1.3vw, .8rem);
  color: var(--ink);
  z-index: 3;
  text-transform: uppercase;
  letter-spacing: .08em;
}
.ac-chip {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border-radius: 999px;
  background: #fff;
  box-shadow: var(--shadow);
  font-size: clamp(.62rem, 1.3vw, .8rem);
  font-weight: 700;
  color: var(--ink);
  white-space: nowrap;
  animation: bob 5s ease-in-out infinite;
}
.ac-chip.c1 {
  right: 6%;
  top: 8%;
  color: #003087;
}
.ac-chip.c2 {
  right: 2%;
  top: 28%;
  animation-delay: -1.2s;
  color: #b45309;
}
.ac-chip.c3 {
  left: 0;
  bottom: 14%;
  animation-delay: -2.4s;
  color: #5f259f;
}
.ac-chip.c4 {
  left: 34%;
  bottom: 2%;
  animation-delay: -3.3s;
  color: #0f766e;
}
.ac-p {
  position: absolute;
  animation: bob 7s ease-in-out infinite;
}
.ac-p.p1 {
  left: 52%;
  top: 4%;
}
.ac-p.p2 {
  left: 0;
  top: 2%;
  animation-delay: -2s;
}
.ac-p.p3 {
  right: 0;
  bottom: 48%;
  animation-delay: -4s;
}
.ap-board {
  position: absolute;
  left: 14%;
  top: 14%;
  width: 58%;
  padding: 34px 20px 20px;
  border-radius: 22px;
  background: #fff;
  box-shadow: var(--shadow-lg);
  transform: rotate(-3deg);
  animation: bob 7s ease-in-out infinite;
