.ars-s:nth-child(4n) {
  color: #facc15;
}
@keyframes star-burst {
  0%, 100% {
    opacity: .35;
    scale: .7;
  }
  50% {
    opacity: 1;
    scale: 1.15;
  }
}
.ars-core {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 36%;
  aspect-ratio: 1;
  border-radius: 30px;
  display: grid;
  place-items: center;
  color: #fff;
  background:
    linear-gradient(
      140deg,
      #f59e0b,
      #ec4899);
  box-shadow: var(--shadow-lg);
  rotate: -6deg;
  animation: bob 5s ease-in-out infinite;
}
.ad-paper {
  position: absolute;
  left: 22%;
  top: 12%;
  width: 50%;
  height: 70%;
  border-radius: 18px;
  background: #fff;
  box-shadow: var(--shadow-lg);
  padding: 28px 22px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  transform: rotate(-4deg);
}
.ad-paper::before {
  content: "";
  position: absolute;
  left: 12%;
  right: -18%;
  top: 6%;
  bottom: -6%;
  border-radius: 18px;
  background: #e0e7ff;
  z-index: -1;
  transform: rotate(8deg);
}
.ad-paper i {
  height: 10px;
  border-radius: 6px;
  background: #e2e8f0;
  transform-origin: left;
  animation: line-in 5s var(--ease) infinite;
}
.ad-paper i:nth-child(odd) {
  width: 86%;
}
.ad-paper i:nth-child(3n) {
  width: 64%;
}
.ad-paper i:nth-child(1) {
  animation-delay: 0s;
}
.ad-paper i:nth-child(2) {
  animation-delay: .2s;
}
.ad-paper i:nth-child(3) {
  animation-delay: .4s;
}
.ad-paper i:nth-child(4) {
  animation-delay: .6s;
}
.ad-paper i:nth-child(5) {
  animation-delay: .8s;
}
.ad-paper i:nth-child(6) {
  animation-delay: 1s;
}
@keyframes line-in {
  0% {
    transform: scaleX(0);
  }
  20%, 90% {
    transform: scaleX(1);
  }
  100% {
    transform: scaleX(0);
  }
}
.ad-stamp {
  position: absolute;
  right: 14%;
  bottom: 14%;
  width: 30%;
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  background:
    conic-gradient(
      #3d5afe,
      #14b8a6,
      #3d5afe);
  box-shadow: 0 0 0 8px rgba(61, 90, 254, .15), var(--shadow-lg);
  animation: stamp 5s var(--ease) infinite;
}
@keyframes stamp {
  0%, 30% {
    transform: scale(1.8) rotate(-30deg);
    opacity: 0;
  }
  42% {
    transform: scale(.92) rotate(0);
    opacity: 1;
  }
  48%, 92% {
    transform: scale(1) rotate(0);
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

