  aspect-ratio: 1;
  margin: 0 auto;
  container-type: inline-size;
}
.vring-orbit {
  position: absolute;
  inset: 14%;
  border-radius: 50%;
  border: 2px dashed rgba(20, 184, 166, .5);
  animation: fr-spin 30s linear infinite;
}
.vring-core {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 40%;
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-content: center;
  justify-items: center;
  text-align: center;
  gap: 2px;
  padding: 12px;
  background:
    linear-gradient(
      160deg,
      #14b8a6,
      #3d5afe);
  color: #fff;
  box-shadow: 0 0 0 14px rgba(20, 184, 166, .14), var(--shadow-lg);
}
.vring-core b {
  font-size: clamp(.72rem, 3cqw, .95rem);
  line-height: 1.2;
}
.vring-core small {
  font-size: clamp(.6rem, 2.4cqw, .74rem);
  opacity: .85;
  line-height: 1.3;
}
.vring-node {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0;
  height: 0;
  transform: rotate(calc(var(--i) * 360deg / var(--n) - 90deg)) translateX(38cqw) rotate(calc(var(--i) * -360deg / var(--n) + 90deg));
}
.vn-ic {
  position: absolute;
  left: -24px;
  top: -24px;
  width: 48px;
  height: 48px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  background: #fff;
  color: var(--teal);
  box-shadow: var(--shadow);
  animation: vnode 6s ease-in-out infinite;
  animation-delay: calc(var(--i) * 1s);
}
@keyframes vnode {
  0%, 12% {
    background: var(--teal);
    color: #fff;
    transform: scale(1.12);
  }
  25%, 100% {
    background: #fff;
    color: var(--teal);
    transform: none;
  }
}
.vn-txt {
  position: absolute;
  top: 28px;
  left: 50%;
  transform: translateX(-50%);
  width: 120px;
  text-align: center;
  font-size: .72rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--ink);
}
.dark-band .vn-txt {
  color: rgba(255, 255, 255, .88);
}
@media (max-width: 480px) {
  .vn-txt {
    width: 92px;
    font-size: .64rem;
  }
  .vn-ic {
    width: 40px;
    height: 40px;
    left: -20px;
    top: -20px;
  }
}
@media (max-width: 860px) {
  .pv-hcp {
    grid-template-columns: 1fr;
  }
  .pv-hcp-list {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 480px) {
  .pv-hcp-list {
    grid-template-columns: 1fr;
  }
}
@keyframes orb-care {
  from {
    transform: rotate(0) translateX(124px) rotate(0);
  }
  to {
    transform: rotate(360deg) translateX(124px) rotate(-360deg);
  }
}
@media (max-width: 900px) {
  .pv-care {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 520px) {
  .pv-care-list {
    grid-template-columns: 1fr;
  }
  .pv-care-orbit {
    transform: scale(.85);
  }
}
@media (max-width: 900px) {
  .pv-bento {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 520px) {
  .pv-bento {
    grid-template-columns: 1fr;
  }
  .pv-bento-card.b0,
  .pv-bento-card.b5 {
    grid-column: auto;
  }
}
.hb-filters {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-bottom: 24px;
}
.hb-monitor {
  position: relative;
  height: 150px;
  border-radius: 24px;
  background: #0b1b3f;
  overflow: hidden;
  margin-bottom: 26px;
  background-image:
    linear-gradient(rgba(255, 255, 255, .05) 1px, transparent 1px),
    linear-gradient(
      90deg,
      rgba(255, 255, 255, .05) 1px,
      transparent 1px);
