}
.hb-line {
  position: absolute;
  inset: 15px 0;
  width: 100%;
  height: calc(100% - 30px);
}
.hb-path {
  fill: none;
  stroke: url(#hb-g);
  stroke-width: 2.5;
}
.hb-glow {
  fill: none;
  stroke: url(#hb-g);
  stroke-width: 8;
  opacity: .25;
  filter: blur(4px);
}
.hb-nodes {
  position: absolute;
  inset: 0;
}
.hb-node {
  position: absolute;
  top: 18px;
  width: 30px;
  height: 30px;
  margin-left: -15px;
  border-radius: 50%;
  font-size: .62rem;
  font-weight: 800;
  color: #fff;
  background: var(--c);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, .2);
  transition: transform .3s var(--ease), box-shadow .3s;
}
.hb-node.on {
  transform: scale(1.35);
  box-shadow: 0 0 0 4px #fff, 0 0 20px var(--c);
}
.hb-node.is-member::after {
  content: "";
  position: absolute;
  right: -2px;
  top: -2px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gold);
}
.hb-cursor {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background:
    linear-gradient(
      transparent,
      #fff,
      transparent);
  transition: left .6s var(--ease);
  box-shadow: 0 0 12px #fff;
}
.hb-card {
  position: relative;
  margin: 0;
  padding: 34px 36px 26px;
  border-radius: 28px;
  background: #fff;
  box-shadow: var(--shadow-lg);
