  animation: page-in .5s var(--ease);
}
.hb-quote-mark {
  position: absolute;
  top: -24px;
  right: 30px;
  width: 60px;
  height: 60px;
  border-radius: 18px;
  display: grid;
  place-items: center;
  background: var(--c);
