}
.hb-card blockquote {
  margin: 0 0 22px;
}
.hb-card blockquote p {
  font-family: var(--font-head);
  font-size: clamp(1.05rem, 2vw, 1.35rem);
  color: var(--ink);
  font-weight: 600;
  line-height: 1.5;
  margin: 0;
}
.hb-card figcaption {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}
.hb-avatar {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 800;
  color: #fff;
  background: var(--c);
  flex: none;
}
.hb-who {
  display: grid;
  line-height: 1.3;
}
.hb-who b {
  color: var(--ink);
}
.hb-who span {
  font-size: .84rem;
  color: var(--muted);
}
.hb-place {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: .86rem;
  font-weight: 600;
  padding: 4px 12px 4px 4px;
  border-radius: 999px;
  background: var(--bg);
