}
.hb-new {
  font-size: .7rem;
  font-weight: 800;
  text-transform: uppercase;
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--gold);
  color: #1f1300;
}
.hb-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 18px;
  font-size: .84rem;
  font-weight: 700;
  color: var(--muted);
}
.hb-nav button {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1.5px solid var(--line);
  display: grid;
  place-items: center;
  color: var(--ink);
