}
.hb-nav button:hover {
  background: var(--ink);
  color: #fff;
}
@media (max-width: 640px) {
  .hb-node {
    width: 22px;
    height: 22px;
    margin-left: -11px;
    font-size: 0;
  }
  .hb-card {
    padding: 30px 20px 20px;
  }
  .hb-place {
    margin-left: 0;
  }
}
.vw-grid {
  columns: 3 300px;
  column-gap: 18px;
}
.vw-card {
