  margin: 0 0 18px;
  padding: 20px;
  border-radius: 22px;
  background: #fff;
  border: 1px solid var(--line);
  box-shadow: var(--shadow-sm);
  transform: rotate(calc((var(--k) - 2.5) * .5deg));
  transition: transform .35s var(--ease), box-shadow .35s;
