/* src/styles/widgets.css */
.help-stack {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
}
.fab-wa {
  position: relative;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #22c55e;
  color: #fff;
  box-shadow: 0 10px 24px -8px rgba(34, 197, 94, .8);
  transition: transform .3s var(--ease);
}
.fab-wa:hover {
  transform: scale(1.08);
}
.fab-wa-ping {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid #22c55e;
  animation: ring-pulse 2.2s ease-out infinite;
}
.fab-tip {
  position: absolute;
  right: 62px;
  top: 50%;
  transform: translateY(-50%) translateX(8px);
  white-space: nowrap;
  background: var(--ink);
  color: #fff;
  font-size: .78rem;
  font-weight: 600;
  padding: 6px 10px;
  border-radius: 8px;
  opacity: 0;
  pointer-events: none;
  transition: all .25s;
}
.fab-wa:hover .fab-tip {
  opacity: 1;
  transform: translateY(-50%);
}
.fab-chat {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0;
  height: 64px;
  padding: 0;
  border-radius: 999px;
  background:
    linear-gradient(
      130deg,
      #ff3d5a,
      #f2542d 55%,
      #f7931e);
  color: #fff;
  box-shadow: 0 16px 36px -12px rgba(232, 52, 78, .8);
  transition: transform .3s var(--ease);
}
.fab-chat:hover {
  transform: translateY(-3px);
}
.fab-face {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  position: relative;
  z-index: 1;
}
.fab-orbit {
  position: absolute;
  left: 0;
  top: 0;
  width: 64px;
  height: 64px;
  animation: fr-spin 6s linear infinite;
}
.fab-orbit i {
  position: absolute;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 8px #fff;
}
.fab-orbit i:nth-child(1) {
  top: -2px;
  left: 28px;
}
.fab-orbit i:nth-child(2) {
  bottom: 4px;
  left: 4px;
  opacity: .7;
  width: 6px;
  height: 6px;
}
.fab-orbit i:nth-child(3) {
  bottom: 4px;
  right: 4px;
  opacity: .5;
  width: 5px;
  height: 5px;
}
.chat-logo .cl-ecg {
  stroke-dasharray: 100;
  animation: hm-draw 2.4s ease-in-out infinite;
}
.fab-label {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-right: 20px;
  font-weight: 700;
  font-size: .9rem;
  white-space: nowrap;
}
.chat-open .fab-label {
  display: none;
}
.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 3px rgba(74, 222, 128, .3);
  display: inline-block;
  animation: eb-pulse 1.6s infinite;
}
.hello-bubble {
  position: relative;
  max-width: 240px;
  padding: 12px 30px 12px 14px;
  border-radius: 16px 16px 4px 16px;
  background: #fff;
  box-shadow: var(--shadow-lg);
  font-size: .86rem;
  text-align: left;
  color: var(--text);
  animation: note-in .5s var(--ease);
}
.hello-bubble b {
  color: var(--ink);
  display: block;
}
.hello-bubble svg {
  position: absolute;
  top: 10px;
  right: 10px;
  color: var(--muted);
}
.chat-win {
  position: fixed;
  right: 20px;
  bottom: 100px;
  width: min(380px, calc(100vw - 24px));
  height: min(600px, calc(100vh - 130px));
  display: flex;
  flex-direction: column;
  border-radius: 26px;
  background: #fff;
  box-shadow: 0 30px 80px -20px rgba(11, 27, 63, .5);
  overflow: hidden;
  transform-origin: bottom right;
  transform: scale(.6) translateY(40px);
  opacity: 0;
  visibility: hidden;
  transition:
    transform .45s var(--ease),
    opacity .3s,
    visibility .45s;
}
.chat-win.is-open {
  transform: none;
  opacity: 1;
  visibility: visible;
}
.chat-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 16px 26px;
  background:
    linear-gradient(
      130deg,
      #0b1b3f,
      #3d1b4f 60%,
      #e8344e);
  color: #fff;
}
.chat-avatar {
  position: relative;
  width: 46px;
  height: 46px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, .14);
  flex: none;
}
.chat-online {
  position: absolute;
  right: -2px;
  bottom: -2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #4ade80;
  border: 2px solid #0b1b3f;
}
.chat-title {
  flex: 1;
  display: grid;
  line-height: 1.3;
}
.chat-title span {
  font-size: .78rem;
  opacity: .85;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.chat-head > button {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  color: #fff;
  background: rgba(255, 255, 255, .1);
}
.chat-body {
  flex: 1;
  overflow-y: auto;
  padding: 18px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  background:
    radial-gradient(
      circle at 1px 1px,
      #e2e8f0 1px,
      transparent 0) 0 0 / 18px 18px,
    #f8fafc;
}
.msg {
  max-width: 86%;
  animation: note-in .35s var(--ease);
}
.msg p {
  margin: 0;
  padding: 10px 14px;
  border-radius: 16px;
  font-size: .9rem;
  line-height: 1.5;
}
.msg-bot p {
  background: #fff;
  color: var(--text);
  border-radius: 4px 16px 16px 16px;
  box-shadow: var(--shadow-sm);
}
.msg-me {
  align-self: flex-end;
}
.msg-me p {
  background: var(--grad-brand);
  color: #fff;
  border-radius: 16px 4px 16px 16px;
}
.msg-links {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 6px;
}
.msg-links a {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: .78rem;
  font-weight: 600;
  padding: 5px 10px;
  border-radius: 999px;
  background: #eef2ff;
  color: var(--blue);
  text-decoration: none;
}
.typing {
  display: flex;
  gap: 4px;
  padding: 12px 14px;
  background: #fff;
  border-radius: 4px 16px 16px 16px;
  width: max-content;
  box-shadow: var(--shadow-sm);
}
.typing i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #94a3b8;
  animation: typing 1.2s infinite;
}
.typing i:nth-child(2) {
  animation-delay: .15s;
}
.typing i:nth-child(3) {
  animation-delay: .3s;
}
@keyframes typing {
  0%, 60%, 100% {
    transform: none;
    opacity: .5;
  }
  30% {
    transform: translateY(-5px);
    opacity: 1;
  }
}
.chat-quick {
  display: flex;
  gap: 6px;
  padding: 10px 12px;
  overflow-x: auto;
  border-top: 1px solid var(--line);
  scrollbar-width: none;
}
.chat-quick button {
  flex: none;
  font-size: .78rem;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: 999px;
  border: 1.5px solid var(--line);
  color: var(--ink);
  white-space: nowrap;
  transition: all .2s;
}
.chat-quick button:hover {
  border-color: var(--red);
  color: var(--red);
}
.chat-form {
  display: flex;
  gap: 8px;
  padding: 10px 12px;
}
.chat-form input {
  flex: 1;
  min-width: 0;
  padding: 11px 14px;
  border-radius: 14px;
  border: 1.5px solid var(--line);
  background: #f8fafc;
  font-size: .92rem;
}
.chat-form input:focus {
  outline: none;
  border-color: var(--blue);
  background: #fff;
}
.chat-form button {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: var(--grad-brand);
  color: #fff;
