.chat-form button:disabled {
  opacity: .4;
}
.chat-foot {
  display: flex;
  align-items: center;
  gap: 4px;
  justify-content: center;
  font-size: .68rem;
  color: var(--muted);
  padding: 0 12px 10px;
  margin: 0;
