.rate-tab {
  position: fixed;
  left: 0;
  top: 50%;
  z-index: 150;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 14px 9px;
  border-radius: 0 16px 16px 0;
  background:
    linear-gradient(
      180deg,
      #f59e0b,
      #e8344e);
