  90% {
    transform: translateY(-50%) translateX(6px);
  }
  94% {
    transform: translateY(-50%) translateX(-2px);
  }
}
.rate-tab-stars {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.rate-tab-stars svg {
  animation: twinkle 2.4s ease-in-out infinite;
  animation-delay: calc(var(--i) * .2s);
}
.rate-tab-text {
