  inset: 0;
  z-index: 400;
  display: grid;
  place-items: center;
  padding: 16px;
  visibility: hidden;
}
.modal.is-open {
  visibility: visible;
}
.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(11, 27, 63, .6);
  backdrop-filter: blur(6px);
  opacity: 0;
  transition: opacity .35s;
}
.modal.is-open .modal-backdrop {
  opacity: 1;
}
.modal-x {
  position: absolute;
  top: 14px;
  right: 14px;
  z-index: 3;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: #f1f5f9;
  color: var(--ink);
}
.mood {
  width: 100%;
  height: 100%;
}
.mood-1 .mood-face {
