.cookie {
  position: fixed;
  left: 50%;
  bottom: 20px;
  z-index: 250;
  width: min(760px, calc(100vw - 24px));
  transform: translateX(-50%);
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 16px;
  align-items: center;
  padding: 18px 20px;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 30px 70px -20px rgba(11, 27, 63, .5);
  border: 1px solid var(--line);
  animation: cookie-in .6s var(--ease);
}
@keyframes cookie-in {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(40px);
  }
}
.cookie-icon {
  width: 50px;
  height: 50px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  background: #fef3c7;
  color: #b45309;
  animation: bob 4s ease-in-out infinite;
}
.cookie-copy strong {
