}
.cookie-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: .84rem;
  font-weight: 600;
  cursor: pointer;
}
.cookie-toggle input {
  position: absolute;
  opacity: 0;
}
.cookie-toggle span {
  width: 38px;
  height: 22px;
  border-radius: 999px;
  background: #cbd5e1;
  position: relative;
  transition: background .25s;
}
.cookie-toggle span::after {
  content: "";
  position: absolute;
  left: 3px;
  top: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: transform .25s var(--ease);
}
.cookie-toggle input:checked + span {
  background: var(--green);
}
.cookie-toggle input:checked + span::after {
  transform: translateX(16px);
}
.cookie-toggle input:focus-visible + span {
  outline: 3px solid var(--blue);
  outline-offset: 2px;
}
.cookie-actions {
  display: grid;
  gap: 8px;
}
@media (max-width: 680px) {
  .cookie {
    grid-template-columns: 1fr;
    bottom: 12px;
  }
  .cookie-icon {
    display: none;
  }
  .cookie-actions {
    grid-template-columns: 1fr 1fr;
  }
}
.cursor-burst i:nth-child(1) {
