}
.cursor-burst i:nth-child(5) {
  --dx: 8px;
  --dy: 22px;
  background: var(--gold);
}
.cursor-burst i:nth-child(6) {
  --dx: -8px;
  --dy: 22px;
}
@keyframes cburst {
  to {
    transform: translate(var(--dx), var(--dy)) scale(.2);
    opacity: 0;
  }
}

/* src/styles/forms.css */
.field {
