  border-radius: 20px;
  background: #fff;
  border: 1px solid var(--line);
}
.glance span {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: #eef2ff;
  color: var(--blue);
  margin-bottom: 6px;
}
.glance:nth-child(2) span {
  background: #ecfdf5;
  color: var(--green);
}
.glance:nth-child(3) span {
  background: #fff7ed;
  color: var(--orange);
}
.glance:nth-child(4) span {
  background: #fdf2f8;
  color: #db2777;
}
.glance b {
  color: var(--ink);
}
.glance small {
  font-size: .84rem;
  color: var(--muted);
}
@media (max-width: 900px) {
  .glance-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 480px) {
  .glance-grid {
    grid-template-columns: 1fr;
  }
}
.legal-layout {
  display: grid;
  grid-template-columns: 270px minmax(0, 1fr);
  gap: 48px;
  align-items: start;
}
.legal-toc {
  position: sticky;
  top: calc(var(--header-h) + 20px);
  display: grid;
  gap: 12px;
}
.legal-toc ol {
  max-height: 60vh;
}
.legal-sections {
  display: grid;
  gap: 22px;
  max-width: 820px;
}
.legal-sec {
  padding: 26px;
  border-radius: 22px;
  background: #fff;
  border: 1px solid var(--line);
  scroll-margin-top: calc(var(--header-h) + 20px);
}
.legal-sec h2 {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 1.3rem;
}
.ls-ic {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: #eef2ff;
  color: var(--blue);
  flex: none;
}
.legal-sec p {
  font-size: .96rem;
}
.legal-sec ul {
  list-style: none;
  display: grid;
  gap: 8px;
}
.legal-sec li {
  position: relative;
  padding-left: 26px;
  font-size: .95rem;
}
.legal-sec li::before {
  content: "";
  position: absolute;
  left: 4px;
  top: .6em;
  width: 10px;
  height: 10px;
  border-radius: 3px;
  background: var(--grad-cool);
  transform: rotate(45deg);
}
.legal-more {
  padding: 20px;
  border-radius: 20px;
  background: var(--navy);
  color: #fff;
}
.legal-more div {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 10px;
}
.legal-more a {
  color: #fff;
  text-decoration: none;
  padding: 6px 14px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, .25);
  font-size: .88rem;
}
.legal-more a:hover {
  background: #fff;
  color: var(--navy);
}
@media (max-width: 960px) {
  .legal-layout {
    grid-template-columns: 1fr;
  }
  .legal-toc {
    position: static;
  }
}
.gauge-wrap {
  padding: 26px;
  border-radius: 30px;
  background: #fff;
  box-shadow: var(--shadow-lg);
  text-align: center;
}
.gauge {
  position: relative;
  width: min(320px, 100%);
  margin: 0 auto;
}
.gauge svg {
  width: 100%;
}
.gauge-needle {
  position: absolute;
  left: 50%;
  bottom: 8%;
  width: 4px;
  height: 44%;
  margin-left: -2px;
  border-radius: 4px;
  background: var(--navy);
  transform-origin: 50% 100%;
  transition: transform .6s var(--ease);
}
.gauge-needle::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -8px;
  width: 18px;
  height: 18px;
  margin-left: -9px;
  border-radius: 50%;
  background: var(--navy);
}
.gauge-val {
  display: block;
  font-family: var(--font-head);
  font-size: 2.4rem;
  color: var(--ink);
  margin-top: 6px;
}
.gauge-val small {
  font-size: 1rem;
  color: var(--muted);
}
.gauge-ctrl {
  display: grid;
  gap: 6px;
  font-size: .84rem;
  font-weight: 600;
  margin: 10px auto;
  max-width: 320px;
}
.gauge-ctrl input {
  accent-color: var(--blue);
  width: 100%;
}
.gauge-state {
  display: inline-block;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 999px;
}
.gauge-state.ok {
  background: #ecfdf5;
  color: #065f46;
}
.gauge-state.mid {
  background: #fffbeb;
  color: #92400e;
}
.gauge-state.low {
  background: #fff1f2;
  color: #9f1239;
}
.gates {
  list-style: none;
  display: grid;
  gap: 12px;
  margin: 18px 0;
}
.gates li {
  display: flex;
  gap: 14px;
  align-items: center;
  padding: 14px;
  border-radius: 18px;
  background: #fff;
  border: 1px solid var(--line);
  border-left: 6px solid var(--c);
}
.gates b {
  font-family: var(--font-head);
  font-size: 1.6rem;
  color: var(--c);
  min-width: 64px;
}
.gates strong {
  display: block;
  color: var(--ink);
}
.gates span {
  font-size: .9rem;
}
.num-tiles {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}
.num-tile {
  padding: 24px;
  border-radius: 22px;
  background: rgba(255, 255, 255, .07);
  border: 1px solid rgba(255, 255, 255, .12);
  text-align: center;
}
.num-tile b {
  display: block;
  font-family: var(--font-head);
  font-size: 2.6rem;
  color: var(--gold);
  line-height: 1.1;
}
.num-tile span {
  font-size: .88rem;
}
@media (max-width: 860px) {
  .num-tiles {
    grid-template-columns: 1fr 1fr;
  }
}
.layer-stack {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  max-width: 900px;
  margin: 0 auto;
}
.layer-stack li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
  border-radius: 16px;
  background: #fff;
  border: 1px solid var(--line);
  font-weight: 600;
  color: var(--ink);
  font-size: .92rem;
}
.layer-stack li svg {
  color: #fff;
  background: hsl(calc(350 - var(--i) * 22), 75%, 55%);
  width: 34px;
  height: 34px;
  padding: 8px;
  border-radius: 10px;
  flex: none;
  box-sizing: border-box;
}
@media (max-width: 640px) {
  .layer-stack {
    grid-template-columns: 1fr;
  }
}
.sm-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-bottom: 48px;
}
.sm-col,
.sm-blog nav {
  padding: 22px;
  border-radius: 22px;
  background: #fff;
  border: 1px solid var(--line);
}
.sm-col h2 {
  font-size: 1.1rem;
}
.sm-col ul,
.sm-blog ul {
  list-style: none;
  display: grid;
  gap: 8px;
}
.sm-col a {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  color: var(--ink);
  font-weight: 500;
}
.sm-blog {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.sm-blog h3 {
  font-size: 1rem;
  color: var(--red);
}
.sm-blog a {
  font-size: .9rem;
  color: var(--text);
  text-decoration: none;
}
.sm-blog a:hover,
.sm-col a:hover {
  color: var(--red);
}
@media (max-width: 860px) {
  .sm-grid,
  .sm-blog {
    grid-template-columns: 1fr;
  }
}
.nf {
  padding: 80px 0 100px;
  text-align: center;
}
.nf-inner {
  max-width: 760px;
}
.nf-monitor {
  position: relative;
  height: 180px;
  border-radius: 28px;
  background: var(--navy);
  overflow: hidden;
  margin-bottom: 30px;
  background-image:
    linear-gradient(rgba(255, 255, 255, .05) 1px, transparent 1px),
    linear-gradient(
      90deg,
      rgba(255, 255, 255, .05) 1px,
      transparent 1px);
  background-size: 20px 20px;
}
.nf-monitor svg {
  position: absolute;
  inset: 20px 0;
  width: 100%;
  height: calc(100% - 40px);
}
.nf-line {
  fill: none;
  stroke: #4ade80;
  stroke-width: 3;
  stroke-dasharray: 100;
  filter: drop-shadow(0 0 6px #4ade80);
  animation: ecg-run 2.6s linear infinite;
}
.nf-code {
  position: absolute;
  right: 24px;
  top: 16px;
  font-family: var(--font-head);
  font-weight: 800;
  font-size: 3rem;
  color: #4ade80;
  opacity: .9;
}
.nf-links {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-top: 26px;
}
.nf-links a {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  border-radius: 16px;
  background: #fff;
  border: 1px solid var(--line);
  text-decoration: none;
  color: var(--ink);
  font-weight: 600;
  transition: all .25s;
}
.nf-links a:hover {
  border-color: var(--red);
  transform: translateY(-3px);
}
.nf-links svg {
  color: var(--red);
}
@media (max-width: 560px) {
  .nf-links {
    grid-template-columns: 1fr 1fr;
  }
}

/* src/styles/v2.css */
p,
.prose li,
.legal-sec li {
  text-align: justify;
  text-justify: inter-word;
  hyphens: auto;
  -webkit-hyphens: auto;
}
.section-head .lead,
.center p,
.cm-head p {
  text-align: justify;
  text-align-last: center;
}
.help-card p,
.footer-cta p {
  text-align: justify;
  text-align-last: left;
}
.section-head.align-left .lead {
  text-align-last: left;
}
.pay-card p,
.steps-path p,
.tip p,
.blog-card p,
.shelf p,
.cm-card p,
.timeline p,
.hx,
.rw-line,
.trend-item,
.tl-copy p,
.sorb-pop,
.glance small,
.num-tile,
.vc-card small,
.ladder p,
.btn,
.msg p,
.chat-foot,
.cookie-copy p,
.field-error,
.field-hint,
.form-fine,
.fine,
small,
.ticket p,
.crumbs,
.tt-track a {
  text-align: left;
  text-align-last: auto;
  hyphens: manual;
}
.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}
.community {
  background:
    radial-gradient(
      900px 400px at 0 0,
      #1d3a8a,
      transparent 60%),
    radial-gradient(
      800px 400px at 100% 100%,
      #5b1840,
      transparent 60%),
    var(--navy);
  color: rgba(255, 255, 255, .82);
  overflow: hidden;
}
.cm-head {
  max-width: 780px;
  margin: 0 auto 44px;
  text-align: center;
}
.cm-head h2 {
  color: #fff;
}
.cm-head p {
  color: rgba(255, 255, 255, .75);
  font-size: 1.06rem;
}
.cm-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
  perspective: 1000px;
}
.cm-card {
  position: relative;
  padding: 24px 22px;
  border-radius: 26px;
  background:
    linear-gradient(
      160deg,
      rgba(255, 255, 255, .1),
      rgba(255, 255, 255, .02));
  border: 1px solid rgba(255, 255, 255, .12);
  overflow: hidden;
  opacity: 0;
  transform: rotateX(25deg) translateY(30px);
  transition: transform .9s var(--ease), opacity .7s;
  transition-delay: calc(var(--i) * 120ms);
}
.community.is-in .cm-card,
html:not(.js-ready) .cm-card {
  opacity: 1;
  transform: none;
}
.cm-card::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 4px;
  background: var(--c);
  box-shadow: 0 0 20px var(--c);
}
.cm-card:hover {
  transform: translateY(-6px) !important;
}
.cm-card strong {
  display: block;
  font-family: var(--font-head);
  font-size: clamp(2rem, 3.4vw, 2.8rem);
  color: #fff;
  line-height: 1.1;
  margin-top: 16px;
}
.cm-card h3 {
  color: var(--c);
  font-size: 1rem;
  margin: 4px 0 2px;
  filter: brightness(1.3);
}
.cm-card small {
  font-size: .82rem;
  opacity: .7;
}
.sv-crowd {
  display: flex;
  height: 52px;
  align-items: center;
}
.sv-crowd > span {
  margin-right: -12px;
  border-radius: 50%;
  box-shadow: 0 0 0 3px var(--navy);
  animation: pop-in .5s var(--ease) both;
  animation-delay: calc(var(--i) * 120ms + .3s);
}
.sv-crowd b {
  margin-left: 18px;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--c);
  color: #fff;
  animation: eb-pulse 1.6s infinite;
}
.sv-coins {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  height: 52px;
}
.svc-col {
  display: flex;
  flex-direction: column-reverse;
  gap: 1px;
}
.svc-col i {
  width: 18px;
  height: 4px;
  border-radius: 4px;
  background:
    linear-gradient(
      90deg,
      #d97706,
      #fde047,
      #d97706);
  opacity: 0;
  animation: coin-stack .4s var(--ease) forwards;
  animation-delay: calc(var(--k) * .15s + var(--j) * .06s + .3s);
}
@keyframes coin-stack {
  from {
    opacity: 0;
    transform: translateY(-20px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.sv-cal {
  display: grid;
  grid-template-columns: repeat(7, 10px);
  gap: 4px;
  height: 52px;
  align-content: center;
}
.sv-cal i {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  background: rgba(255, 255, 255, .12);
}
.sv-cal i.on {
  background: var(--c);
  box-shadow: 0 0 8px var(--c);
  animation: pop-in .4s var(--ease) both;
  animation-delay: calc(var(--i) * 50ms + .3s);
}
.sv-ring {
  position: relative;
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  color: var(--c);
}
.sv-ring svg {
  position: absolute;
  inset: 0;
  transform: rotate(-90deg);
}
.sv-ring .r-bg {
  fill: none;
  stroke: rgba(255, 255, 255, .12);
  stroke-width: 8;
}
.sv-ring .r-fg {
  fill: none;
  stroke: var(--c);
  stroke-width: 8;
  stroke-linecap: round;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 2s var(--ease) .4s;
}
.community.is-in .sv-ring .r-fg {
  stroke-dashoffset: 8;
}
@media (max-width: 960px) {
  .cm-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 480px) {
  .cm-grid {
    grid-template-columns: 1fr;
  }
}
.rw-roles {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-bottom: 30px;
}
.rw-roles button {
  --c: #3d5afe;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 20px;
  border-radius: 16px;
  font-weight: 700;
  background: #fff;
  border: 2px solid color-mix(in srgb, var(--c) 30%, white);
  color: var(--c);
  transition: all .35s var(--ease);
}
.rw-roles button:hover {
  transform: translateY(-3px);
}
.rw-roles button.on {
  background: var(--c);
  color: #fff;
  box-shadow: 0 14px 30px -14px var(--c);
  transform: translateY(-3px) scale(1.04);
}
.rw-stage {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(24px, 5vw, 60px);
  align-items: center;
}
.rw-dial {
  position: relative;
  width: min(100%, 480px);
  aspect-ratio: 1;
  margin: 0 auto;
  container-type: inline-size;
  animation: pop-in .6s var(--ease);
}
.rw-dial::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background:
    conic-gradient(
      from 0deg,
      color-mix(in srgb, var(--c) 18%, white),
      color-mix(in srgb, var(--c2) 18%, white),
      color-mix(in srgb, var(--c) 18%, white));
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--c) 30%, white), var(--shadow-lg);
}
.rw-dial::after {
  content: "";
  position: absolute;
  inset: 14%;
  border-radius: 50%;
  border: 2px dashed color-mix(in srgb, var(--c) 40%, white);
  animation: fr-spin 30s linear infinite;
}
.rw-spin {
  position: absolute;
  inset: 0;
  transform: rotate(var(--rot));
  transition: transform 1s cubic-bezier(.34, 1.4, .64, 1);
  z-index: 1;
}
.rw-node {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0;
  height: 0;
  transform: rotate(var(--a)) translateY(-41cqw);
}
.rwn-in {
  position: absolute;
  left: -24px;
  top: -24px;
  width: 48px;
  height: 48px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  background: #fff;
  color: var(--c);
  box-shadow: var(--shadow);
  transform: rotate(calc((var(--a) + var(--rot)) * -1));
  transition:
    transform 1s cubic-bezier(.34, 1.4, .64, 1),
    background .3s,
    color .3s,
    scale .3s;
}
.rw-node.on .rwn-in {
  background:
    linear-gradient(
      140deg,
      var(--c),
      var(--c2));
  color: #fff;
  scale: 1.25;
  box-shadow: 0 0 0 6px color-mix(in srgb, var(--c) 20%, transparent), 0 14px 30px -10px var(--c);
}
.rw-core {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 48%;
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  z-index: 2;
  display: grid;
  place-content: center;
  justify-items: center;
  text-align: center;
  gap: 4px;
  padding: 16px;
  background: #fff;
  box-shadow: 0 0 0 10px rgba(255, 255, 255, .6), var(--shadow-lg);
}
.rw-gift {
  width: 56px;
  height: 56px;
  border-radius: 18px;
  display: grid;
  place-items: center;
  color: #fff;
  background:
    linear-gradient(
      140deg,
      var(--c),
      var(--c2));
  animation: gift-shake 2.6s ease-in-out infinite;
}
@keyframes gift-shake {
  0%, 80%, 100% {
    transform: rotate(0);
  }
  84% {
    transform: rotate(-10deg) scale(1.08);
  }
  88% {
    transform: rotate(10deg) scale(1.08);
  }
  92% {
    transform: rotate(-6deg);
  }
}
.rw-core b {
  font-family: var(--font-head);
  color: var(--ink);
  font-size: clamp(.9rem, 3.8cqw, 1.2rem);
  line-height: 1.2;
  animation: rh-in .45s var(--ease);
}
.rw-core b,
.rw-core small {
  text-align: center !important;
}
.rw-core small {
  color: var(--muted);
  font-size: clamp(.68rem, 2.8cqw, .84rem);
  line-height: 1.35;
  animation: rh-in .45s var(--ease) .05s both;
}
.rw-pointer {
  position: absolute;
  left: 50%;
  top: -2px;
  width: 0;
  height: 0;
  margin-left: -10px;
  border: 10px solid transparent;
  border-top: 16px solid var(--c);
  z-index: 3;
  filter: drop-shadow(0 4px 6px rgba(0, 0, 0, .2));
}
.rw-line {
  font-family: var(--font-head);
  font-weight: 700;
  font-size: 1.3rem;
  color: var(--ink);
  margin-bottom: 16px;
  text-align: left;
}
.rw-list ul {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 14px;
}
.rw-list button {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 12px;
  background: #fff;
  border: 1.5px solid var(--line);
  font-size: .88rem;
  font-weight: 600;
  color: var(--ink);
  text-align: left;
  transition: all .3s var(--ease);
}
.rw-list button svg {
  color: var(--c);
  flex: none;
}
.rw-list li.on button {
