  background:
    linear-gradient(
      160deg,
      #fff7ed,
      #f8fafc 60%);
}
.join.theme-patient {
  --rc: #10b981;
  background:
    linear-gradient(
      160deg,
      #ecfdf5,
      #f8fafc 60%);
}
.join {
  transition: background .8s;
}
.join-card {
