  font-weight: 600;
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .14);
  border: 1px solid rgba(255, 255, 255, .2);
  color: #fff;
  animation: pop-in .4s var(--ease) both;
  animation-delay: calc(var(--i) * 70ms + .4s);
}
.g-ic {
  width: 26px;
  height: 26px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: #f1f5f9;
  transition:
    transform .4s cubic-bezier(.34, 1.8, .64, 1),
    background .3s,
    color .3s;
}
.g-female {
  color: #ec4899;
}
.g-male {
  color: #3d5afe;
}
.g-genderOther {
  color: #8b5cf6;
}
.g-eyeOff {
  color: #64748b;
}
.chip-pick label:hover .g-ic {
  transform: rotate(-12deg) scale(1.15);
}
.chip-pick label.on .g-ic {
  background: rgba(255, 255, 255, .25);
  color: #fff;
  animation: g-bounce .6s cubic-bezier(.34, 1.8, .64, 1);
}
@keyframes g-bounce {
  0% {
    transform: scale(.4) rotate(-40deg);
  }
  100% {
    transform: none;
  }
}
.dob-cake {
  position: relative;
  animation: cake-wobble 3s ease-in-out infinite;
}
.dob-cake::after {
  content: "";
  position: absolute;
  left: 50%;
  top: -5px;
  width: 5px;
  height: 8px;
  margin-left: -2.5px;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  background: linear-gradient(#fde047, #f97316);
  animation: flame .4s ease-in-out infinite alternate;
}
@keyframes flame {
  from {
    transform: scale(1) rotate(-6deg);
  }
  to {
    transform: scale(1.2, .9) rotate(6deg);
  }
}
@keyframes cake-wobble {
  0%, 90%, 100% {
    transform: rotate(0);
  }
  94% {
    transform: rotate(-8deg);
  }
  97% {
    transform: rotate(8deg);
  }
}
.dob-btn:focus-visible .dob-cake,
.dob.is-open .dob-cake {
  background: #fce7f3;
  transform: scale(1.1);
}
.dob-grid button.sel {
  background:
    linear-gradient(
      140deg,
      var(--rc, #e8344e),
      #f7931e);
  animation: g-bounce .5s cubic-bezier(.34, 1.8, .64, 1);
}
.cover {
  isolation: isolate;
}
.cv-prop.pr0 {
  right: 42%;
  top: 14%;
}
.cv-prop.pr1 {
  right: 6%;
  top: 10%;
  animation-delay: -1.3s;
