}
.cv-prop.pr2 {
  left: 36%;
  bottom: 10%;
  animation-delay: -2.6s;
}
.footer-aurora i {
  position: absolute;
  border-radius: 50%;
  filter: blur(90px);
  opacity: .35;
  animation: blob 16s ease-in-out infinite;
}
.footer-aurora i:nth-child(1) {
  width: 420px;
  height: 420px;
  background: #e8344e;
  top: -160px;
  left: -120px;
}
.footer-aurora i:nth-child(2) {
  width: 380px;
  height: 380px;
  background: #3d5afe;
  top: 30%;
  right: -120px;
  animation-direction: reverse;
}
.footer-aurora i:nth-child(3) {
  width: 300px;
  height: 300px;
  background: #14b8a6;
  bottom: -120px;
  left: 40%;
}
.footer-ecg {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  width: 100%;
  height: 80px;
  opacity: .6;
}
.footer-ecg path {
  fill: none;
  stroke: #ff3d5a;
  stroke-width: 2.5;
  stroke-dasharray: 20 80;
  filter: drop-shadow(0 0 6px #ff3d5a);
  animation: ecg-run 4s linear infinite;
}
.footer-cta {
  position: relative;
  z-index: 1;
}
.fc-stack {
  position: relative;
  width: 96px;
  height: 96px;
  perspective: 600px;
  flex: none;
}
.fc-coin {
  position: absolute;
  left: 0;
  top: 0;
  width: 84px;
  height: 84px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background:
    radial-gradient(
      circle at 35% 30%,
      #fff7c2,
      #facc15 45%,
      #d97706);
  box-shadow: inset 0 0 0 5px rgba(255, 255, 255, .35), 0 0 30px rgba(250, 204, 21, .4);
  animation: coin-cycle 8s linear infinite;
  animation-delay: calc(var(--i) * -2s);
}
.fc-coin b {
  font-family: var(--font-head);
  font-size: 2.1rem;
  color: #7c4a00;
}
@keyframes coin-cycle {
  0% {
    transform: rotateY(0) translateZ(0);
    opacity: 0;
  }
  5% {
    opacity: 1;
  }
  25% {
    transform: rotateY(360deg);
    opacity: 1;
  }
  30%, 100% {
    opacity: 0;
    transform: rotateY(450deg);
  }
}
.footer-main {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1.1fr 1.3fr;
  gap: 30px;
  padding-bottom: 40px;
}
.fm-brand p {
  font-size: .92rem;
  margin: 16px 0 18px;
  text-align: left;
}
.fm-logo {
  display: inline-block;
  text-decoration: none;
}
.fm-col h3 {
  color: #fff;
  font-size: .8rem;
  text-transform: uppercase;
  letter-spacing: .12em;
  margin-bottom: 16px;
}
.fm-col ul {
  list-style: none;
  display: grid;
  gap: 10px;
}
.fm-col a {
  position: relative;
  color: rgba(255, 255, 255, .72);
  text-decoration: none;
  font-size: .92rem;
  transition: color .2s;
}
.fm-col a::before {
  content: "";
  position: absolute;
  left: 0;
  bottom: -2px;
  width: 100%;
  height: 1.5px;
  background: var(--grad-brand);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .3s var(--ease);
}
.fm-col a:hover {
  color: #fff;
}
.fm-col a:hover::before {
  transform: scaleX(1);
}
.fm-contact li {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  font-size: .9rem;
}
.fm-contact svg {
  flex: none;
  margin-top: 3px;
  color: var(--orange);
}
.fm-social {
  list-style: none;
  display: flex;
  gap: 12px;
}
.sorb {
  position: relative;
}
.sorb-ic {
  width: 46px;
  height: 46px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  color: #fff;
  text-decoration: none;
  transition: transform .35s cubic-bezier(.34, 1.8, .64, 1);
  animation: float-y 4s ease-in-out infinite;
  animation-delay: calc(var(--i) * -.6s);
}
.sorb-facebook .sorb-ic {
  background: #1877f2;
}
.sorb-linkedin .sorb-ic {
  background: #0a66c2;
}
.sorb-youtube .sorb-ic {
  background: #ff0000;
}
.sorb-instagram .sorb-ic {
  background:
    radial-gradient(
      circle at 30% 107%,
      #fdf497 0%,
      #fd5949 45%,
      #d6249f 60%,
      #285aeb 90%);
}
.sorb-ic:hover {
  transform: translateY(-4px) rotate(-8deg) scale(1.1);
}
.sorb-qr {
  position: absolute;
  right: -6px;
  bottom: -6px;
  width: 20px;
  height: 20px;
  border-radius: 6px;
  display: grid;
  place-items: center;
  background: #fff;
  color: var(--ink);
  box-shadow: var(--shadow-sm);
}
.sorb-pop {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 12px);
  transform: translateX(-50%) scale(.6);
  opacity: 0;
  pointer-events: none;
  padding: 10px;
  border-radius: 16px;
  background: #fff;
  box-shadow: var(--shadow-lg);
  display: grid;
  justify-items: center;
  gap: 4px;
  transition: all .35s cubic-bezier(.34, 1.6, .64, 1);
  z-index: 5;
}
.sorb-pop small {
  color: var(--ink);
  font-size: .7rem;
  font-weight: 600;
}
.sorb.is-open .sorb-pop {
  opacity: 1;
  transform: translateX(-50%) scale(1);
  pointer-events: auto;
}
.footer-trust {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 32px;
  align-items: center;
  padding: 28px 30px;
  border-radius: 28px;
  background: rgba(255, 255, 255, .05);
  border: 1px solid rgba(255, 255, 255, .1);
  margin-bottom: 24px;
}
.ft-label {
  display: block;
  font-size: .72rem;
  text-transform: uppercase;
  letter-spacing: .14em;
  margin-bottom: 12px;
  color: rgba(255, 255, 255, .6);
}
.fr-show {
  display: flex;
  align-items: center;
  gap: 16px;
}
.frs-card {
  position: relative;
  display: block;
  width: 190px;
  padding: 8px 12px;
  border-radius: 16px;
  background: #fff;
  overflow: hidden;
  transform: perspective(600px) rotateY(-10deg);
  transition: transform .5s var(--ease);
  box-shadow: 0 20px 40px -20px rgba(0, 0, 0, .5);
}
.frs-card:hover,
.fr-show:hover .frs-card {
  transform: perspective(600px) rotateY(0) scale(1.04);
}
.frs-card img {
  width: 100%;
  height: auto;
  display: block;
}
.badge-parade {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  align-items: center;
}
.bp-item {
  width: 108px;
  height: 78px;
  perspective: 700px;
  animation: float-y 4.5s ease-in-out infinite;
  animation-delay: calc(var(--i) * -.8s);
  outline: none;
}
.bp-item.is-round {
  width: 78px;
}
.bp-inner {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transition: transform .7s cubic-bezier(.34, 1.4, .64, 1);
}
.bp-item:hover .bp-inner,
.bp-item:focus .bp-inner {
  transform: rotateY(180deg);
}
.bp-front,
.bp-back {
  position: absolute;
  inset: 0;
  border-radius: 16px;
  display: grid;
  place-items: center;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  overflow: hidden;
}
.bp-front {
  background: #fff;
  padding: 8px;
  box-shadow: 0 12px 24px -12px rgba(0, 0, 0, .5);
}
.is-round .bp-front {
  border-radius: 50%;
}
.bp-front img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}
.bp-back {
  transform: rotateY(180deg);
  background: var(--grad-brand);
  color: #fff;
  text-align: center;
  padding: 6px;
  align-content: center;
}
.is-round .bp-back {
  border-radius: 50%;
}
.bp-back b {
  font-size: .72rem;
  line-height: 1.1;
}
.bp-back small {
  font-size: .58rem;
  line-height: 1.2;
  opacity: .9;
  text-align: center;
}
.badge-parade.is-light {
  justify-content: center;
  margin-top: 18px;
}
.badge-parade.is-light .bp-front {
  box-shadow: var(--shadow);
  border: 1px solid var(--line);
}
@media (max-width: 1080px) {
  .footer-main {
    grid-template-columns: 1fr 1fr 1fr;
  }
  .fm-brand {
    grid-column: 1 / -1;
  }
  .footer-trust {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 640px) {
  .footer-main {
    grid-template-columns: 1fr 1fr;
  }
  .fm-contact {
    grid-column: 1 / -1;
  }
  .footer-trust {
    padding: 20px;
  }
  .fr-show {
    flex-wrap: wrap;
  }
  .bp-item {
    width: 92px;
    height: 66px;
  }
  .bp-item.is-round {
    width: 66px;
  }
}
.captcha-body input::placeholder {
  letter-spacing: normal;
  text-transform: none;
  font-weight: 500;
}

/* src/styles/v3.css */
:root {
  --navy: #1b1035;
  --navy-2: #2a1a52;
  --ink: #170f2e;
  --text: #3d3a52;
  --muted: #6b6884;
  --line: #e7e5f2;
  --bg: #f6f7fc;
  --orange: #ff6a2c;
  --orange-2: #ffb020;
  --red: #ef2d56;
  --blue: #2457f5;
  --violet: #8a4dff;
  --teal: #00a88a;
  --green: #00b386;
  --amber: #ffb020;
  --grad-brand:
    linear-gradient(
      120deg,
      #ef2d56 0%,
      #ff6a2c 50%,
      #ffb020 100%);
  --grad-cool:
    linear-gradient(
      120deg,
      #2457f5 0%,
      #8a4dff 100%);
  --hcp-1: #2457f5;
  --hcp-2: #8a4dff;
  --hcp-soft: #eef0ff;
  --cg-1: #ff9f1c;
  --cg-2: #ff4f6d;
  --cg-soft: #fff3e6;
  --pt-1: #00b386;
  --pt-2: #12c2e9;
  --pt-soft: #e5faf4;
  --shadow: 0 14px 34px -14px rgba(27, 16, 53, 0.22);
  --shadow-lg: 0 34px 80px -30px rgba(27, 16, 53, 0.42);
}
body {
  background: var(--bg);
}
.rgrade-hcp {
  --g1: var(--hcp-1);
  --g2: var(--hcp-2);
  --gs: var(--hcp-soft);
}
.rgrade-caregiver {
  --g1: var(--cg-1);
  --g2: var(--cg-2);
  --gs: var(--cg-soft);
}
.rgrade-patient {
  --g1: var(--pt-1);
  --g2: var(--pt-2);
  --gs: var(--pt-soft);
}
.t-hcp {
  --g1: var(--hcp-1);
  --g2: var(--hcp-2);
  --gs: var(--hcp-soft);
}
.t-caregiver {
  --g1: var(--cg-1);
  --g2: var(--cg-2);
  --gs: var(--cg-soft);
}
.t-patient {
  --g1: var(--pt-1);
  --g2: var(--pt-2);
  --gs: var(--pt-soft);
}
.dark-band {
  background:
    radial-gradient(
      1000px 500px at 0 0,
      #3b1d78 0%,
      transparent 60%),
    radial-gradient(
      900px 500px at 100% 100%,
      #7a1f3d 0%,
      transparent 60%),
    var(--navy);
}
.btn-primary {
  background: var(--grad-brand);
  box-shadow: 0 12px 26px -12px rgba(255, 106, 44, 0.85);
}
.btn-ghost {
  border-color: #dcd8ee;
}
.btn-ghost:hover {
  border-color: var(--orange);
  color: var(--orange);
}
.text-link {
  color: var(--orange);
}
.eyebrow i::after {
  box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 20%, transparent);
}
.site-header {
  background: rgba(255, 255, 255, .86);
  border-bottom: 1px solid rgba(231, 229, 242, .8);
}
.site-header::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 3px;
  background:
    linear-gradient(
      90deg,
      #ef2d56,
      #ff6a2c,
      #ffb020,
      #ff6a2c,
      #ef2d56);
