  animation: strip 8s linear infinite;
}
@keyframes strip {
  to {
    background-position: 200% 0;
  }
}
.site-header.is-scrolled {
  background: rgba(255, 255, 255, .95);
  box-shadow: 0 10px 30px -20px rgba(27, 16, 53, .35);
}
.header-progress {
