    linear-gradient(
      90deg,
      #ff6a2c,
      #ffb020);
  height: 3px;
}
.main-nav {
  padding: 5px;
  border-radius: 999px;
  background:
    linear-gradient(
      135deg,
      #1b1035,
      #2e1a5c);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .06), 0 10px 26px -14px rgba(27, 16, 53, .8);
}
.nav-pill {
  background:
    linear-gradient(
      120deg,
      #ff6a2c,
      #ffb020);
  box-shadow: 0 6px 18px -6px rgba(255, 106, 44, .9);
