.btn-login:hover,
.btn-login.on {
  background: #1b1035;
  color: #fff;
}
.btn-join {
  background:
    linear-gradient(
      120deg,
      #ff6a2c,
      #ffb020);
  color: #1b1035;
  box-shadow: 0 10px 22px -10px rgba(255, 106, 44, .9);
}
.burger {
  border-color: #1b1035;
