/* src/styles/v4.css */
@property --num { syntax: "<integer>"; inherits: false; initial-value: 0; }
@keyframes pt-count {
  0% {
    --num: 0;
  }
  60%, 100% {
    --num: var(--to);
  }
}
.count-up {
  --num: 0;
  counter-reset: n var(--num);
  animation: pt-count 6s cubic-bezier(.2, .8, .2, 1) infinite;
  font-variant-numeric: tabular-nums;
}
.count-up::before {
  content: attr(data-pre) counter(n);
}
.gcoin {
  position: absolute;
  width: 9cqw;
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background:
    radial-gradient(
      circle at 35% 30%,
      #fff7c2,
      #fcd34d 45%,
      #d97706);
  box-shadow:
    inset 0 0 0 .5cqw rgba(255, 255, 255, .45),
    0 .7cqw 0 #b45309,
    0 1.6cqw 1.6cqw rgba(146, 64, 14, .3);
}
.gcoin b {
  font-family: var(--font-head);
  font-weight: 800;
  font-size: 4cqw;
  color: #92400e;
}
@keyframes float-y {
  0%, 100% {
    translate: 0 0;
  }
  50% {
    translate: 0 -1.6cqw;
  }
}
.stage {
  position: relative;
  width: min(100%, 540px);
  aspect-ratio: 1;
  margin: 0 auto;
  perspective: 1200px;
  container-type: inline-size;
}
.stage-3d {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transform: rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg));
  transition: transform .4s var(--ease);
}
.stage-pad {
  position: absolute;
  left: 6%;
  width: 88%;
  aspect-ratio: 1;
  bottom: -34%;
  border-radius: 50%;
  transform: rotateX(78deg);
  background:
    radial-gradient(
      circle,
      color-mix(in srgb, var(--g1) 30%, white) 0,
      color-mix(in srgb, var(--g2) 14%, transparent) 50%,
      transparent 68%);
}
.stage-pad::before {
  content: "";
  position: absolute;
  inset: 10%;
  border-radius: 50%;
  border: 3px dashed color-mix(in srgb, var(--g1) 55%, transparent);
  animation: fr-spin 26s linear infinite;
}
.stage-pad::after {
  content: "";
  position: absolute;
  inset: 24%;
  border-radius: 50%;
  border: 8px solid color-mix(in srgb, var(--g2) 22%, transparent);
  animation: pad-pulse 3s ease-in-out infinite;
}
@keyframes pad-pulse {
  0%, 100% {
    transform: scale(1);
    opacity: .8;
  }
  50% {
    transform: scale(1.08);
    opacity: .4;
  }
}
.s-chip {
  position: absolute;
  z-index: 8;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border-radius: 999px;
  background: #fff;
  box-shadow: var(--shadow);
  font-size: clamp(.6rem, 2.5cqw, .8rem);
  font-weight: 700;
  color: var(--ink);
  white-space: nowrap;
  transform: translateZ(70px);
  animation: float-y 5s ease-in-out infinite;
}
.s-chip svg {
  color: var(--g1);
}
.s-badge {
  position: absolute;
  z-index: 8;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 14px 7px 7px;
  border-radius: 18px;
  background: rgba(255, 255, 255, .94);
  backdrop-filter: blur(8px);
  box-shadow: var(--shadow-lg);
  transform: translateZ(80px);
  animation: float-y 6s ease-in-out infinite;
  animation-delay: -2s;
}
.s-badge .persona {
  border-radius: 50%;
  box-shadow: 0 0 0 3px var(--gs);
}
.s-badge b {
  display: block;
  font-size: clamp(.64rem, 2.7cqw, .86rem);
  color: var(--ink);
}
.s-badge small {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: clamp(.56rem, 2.3cqw, .72rem);
  color: var(--g1);
  font-weight: 600;
}
.vm-monitor {
  position: absolute;
  z-index: 3;
  left: 0;
  top: 25%;
  width: 70%;
  transform: translateZ(30px) rotateY(14deg) rotateX(3deg);
  transform-style: preserve-3d;
}
.vm-screen {
  position: relative;
  padding: 3cqw;
  border-radius: 4cqw;
  background:
    linear-gradient(rgba(52, 245, 197, .06) 1px, transparent 1px) 0 0 / 100% 4cqw,
    linear-gradient(
      90deg,
      rgba(52, 245, 197, .06) 1px,
      transparent 1px) 0 0 / 4cqw 100%,
    radial-gradient(
      120% 90% at 30% 0,
      #22184a,
      #0d0a24 70%);
  border: 1.3cqw solid #2a1f56;
  box-shadow:
    0 0 0 .4cqw #3d2f7a,
    0 30px 60px -24px rgba(36, 87, 245, .7),
    inset 0 0 6cqw rgba(52, 245, 197, .08);
  overflow: hidden;
}
.vm-screen::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      115deg,
      rgba(255, 255, 255, .1),
      transparent 40%);
  pointer-events: none;
}
.vm-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 6px;
  font-size: clamp(.5rem, 2.3cqw, .74rem);
  color: #b8b3d9;
  font-weight: 600;
}
.vm-live {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #fff;
}
.vm-live i {
  width: 1.8cqw;
  height: 1.8cqw;
  border-radius: 50%;
  background: #ef2d56;
  box-shadow: 0 0 0 0 rgba(239, 45, 86, .6);
  animation: live-ping 1.6s ease-out infinite;
}
@keyframes live-ping {
  0% {
    box-shadow: 0 0 0 0 rgba(239, 45, 86, .7);
  }
  100% {
    box-shadow: 0 0 0 2.6cqw rgba(239, 45, 86, 0);
  }
}
.vm-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(138, 77, 255, .25);
  color: #d8ccff;
}
.vm-ecg {
  display: block;
  width: 100%;
  height: 19cqw;
  margin: 1.5cqw 0;
  overflow: visible;
}
.vm-ecg path {
  fill: none;
  stroke-linejoin: round;
  stroke-linecap: round;
}
.vm-trace {
  stroke: rgba(52, 245, 197, .9);
  stroke-width: 2.4;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  animation: vm-draw 2.4s linear infinite;
}
.vm-glow {
  stroke: rgba(52, 245, 197, .35);
  stroke-width: 7;
  filter: blur(3px);
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  animation: vm-draw 2.4s linear infinite;
}
@keyframes vm-draw {
  0% {
    stroke-dashoffset: 100;
    opacity: 1;
  }
  88% {
    stroke-dashoffset: 0;
    opacity: 1;
  }
  100% {
    stroke-dashoffset: 0;
    opacity: 0;
  }
