}
.vm-cell.big .count-up {
  font-size: clamp(.9rem, 5cqw, 1.6rem);
  background:
    linear-gradient(
      120deg,
      #fde68a,
      #34f5c5);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.vm-ok {
