  justify-self: start;
  background: none;
  padding: 0;
}
.join-reject {
  display: grid;
  justify-items: center;
  text-align: center;
  gap: 12px;
  padding: 30px 10px;
}
.join-reject p {
  text-align: center !important;
  text-align-last: center;
  max-width: 46ch;
}
.jr-ic {
  width: 84px;
  height: 84px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  background:
    linear-gradient(
      135deg,
      #2457f5,
      #8a4dff);
  box-shadow: 0 0 0 10px rgba(36, 87, 245, .12);
  animation: stamp-in .6s cubic-bezier(.34, 1.8, .64, 1);
}
@keyframes stamp-in {
  from {
    transform: scale(.3) rotate(-30deg);
    opacity: 0;
  }
}
.jr-count {
  font-size: .9rem;
  color: var(--muted);
}
.jr-count b {
  color: var(--ink);
  font-size: 1.1rem;
}
.jr-bar {
  width: min(320px, 90%);
  height: 6px;
  border-radius: 6px;
  background: #eceaf6;
  overflow: hidden;
}
.jr-bar i {
  display: block;
  height: 100%;
  background:
    linear-gradient(
      90deg,
      #2457f5,
      #8a4dff);
  transform-origin: left;
  animation: timer linear forwards;
}
.jr-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-top: 6px;
}
.s-atlas {
  background:
    radial-gradient(
      900px 420px at 15% 20%,
      #fdf0f6,
      transparent 60%),
    radial-gradient(
      700px 400px at 90% 90%,
      #eef2ff,
      transparent 60%),
    var(--bg);
}
.atlas {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(24px, 4vw, 60px);
  align-items: center;
}
.atlas-wheel {
  position: relative;
  width: min(100%, 520px);
  aspect-ratio: 1;
  margin: 0 auto;
}
.aw-svg {
  width: 100%;
  height: 100%;
  overflow: visible;
  filter: drop-shadow(0 30px 40px rgba(27, 16, 53, .14));
}
.aw-dash {
  fill: none;
  stroke: color-mix(in srgb, var(--ac) 40%, #d9d6ea);
  stroke-width: 1.5;
  stroke-dasharray: 2 7;
  transform-origin: 0 0;
  animation: fr-spin 60s linear infinite;
}
.aw-rot {
  transition: transform 1s cubic-bezier(.6, -.15, .3, 1.25);
}
.aw-seg {
  cursor: pointer;
  transition: transform .6s cubic-bezier(.34, 1.5, .64, 1);
}
.aw-seg path {
  fill: var(--c);
  opacity: .78;
  stroke: #fff;
  stroke-width: 1.5;
  transition: opacity .3s, filter .3s;
}
.aw-seg:hover path {
  opacity: .95;
}
.aw-seg.on path {
  opacity: 1;
  filter: drop-shadow(0 6px 10px color-mix(in srgb, var(--c) 60%, transparent));
}
.aw-ic {
  color: #fff;
  transform: rotate(calc(var(--w, 0deg) * -1));
  transform-box: fill-box;
  transform-origin: center;
  transition: transform 1s cubic-bezier(.6, -.15, .3, 1.25);
}
.aw-seg.on .aw-ic {
  animation: ic-bounce 1.2s ease-in-out infinite;
}
@keyframes ic-bounce {
  0%, 100% {
    scale: 1;
  }
  50% {
    scale: 1.18;
  }
}
.aw-core {
  fill: #fff;
  filter: drop-shadow(0 10px 22px rgba(27, 16, 53, .12));
}
.aw-pulse {
  fill: none;
  stroke: var(--ac);
  stroke-width: 2;
  transform-origin: 0 0;
  animation: aw-pulse 2.4s ease-out infinite;
}
@keyframes aw-pulse {
  0% {
    transform: scale(.85);
    opacity: .9;
  }
  100% {
    transform: scale(1.06);
    opacity: 0;
  }
}
.aw-center {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  width: 52%;
  display: grid;
  justify-items: center;
  gap: 6px;
  text-align: center;
  animation: rh-in .5s var(--ease);
}
.awc-ic {
  width: 64px;
  height: 64px;
  border-radius: 22px;
  display: grid;
  place-items: center;
  color: #fff;
  background:
    linear-gradient(
      135deg,
      var(--ac),
      color-mix(in srgb, var(--ac) 60%, #1b1035));
  box-shadow: 0 14px 28px -12px var(--ac);
  animation: float-y 3s ease-in-out infinite;
  container-type: normal;
}
.aw-center b {
  font-family: var(--font-head);
  font-size: clamp(.9rem, 2.2vw, 1.25rem);
  color: var(--ink);
  line-height: 1.2;
}
.aw-center small {
  font-weight: 700;
  color: var(--ac);
  font-size: .82rem;
}
.aw-pointer {
  position: absolute;
  left: 50%;
  top: -2%;
  translate: -50% 0;
  width: 0;
  height: 0;
  border-left: 10px solid transparent;
  border-right: 10px solid transparent;
  border-top: 16px solid var(--ink);
  filter: drop-shadow(0 4px 4px rgba(0, 0, 0, .2));
}
.atlas-side {
  display: grid;
  gap: 18px;
  min-width: 0;
}
.as-total {
  display: flex;
  align-items: center;
  gap: 14px;
}
.as-total b {
  font-family: var(--font-head);
  font-size: clamp(2.6rem, 5vw, 3.8rem);
  line-height: 1;
  background:
    linear-gradient(
      120deg,
      #ef2d56,
      #8a4dff,
      #12c2e9);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.as-total span {
  font-weight: 600;
  color: var(--muted);
  line-height: 1.3;
  text-align: left;
}
.as-tabs {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 6px;
}
.as-tabs button {
  aspect-ratio: 1;
  border-radius: 12px;
  display: grid;
  place-items: center;
  color: var(--c);
  background: color-mix(in srgb, var(--c) 12%, white);
  transition: all .3s var(--ease);
}
.as-tabs button:hover {
  transform: translateY(-3px);
}
.as-tabs button.on {
  color: #fff;
  background: var(--c);
  box-shadow: 0 10px 18px -8px var(--c);
  transform: translateY(-3px) scale(1.08);
}
.as-panel {
  padding: 20px;
  border-radius: 24px;
  background: #fff;
  box-shadow: var(--shadow);
  border-top: 5px solid var(--ac);
  animation: rh-in .45s var(--ease);
}
.as-panel h3 {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.15rem;
  margin-bottom: 12px;
  color: var(--ink);
}
.as-panel h3 svg {
  color: var(--ac);
}
.as-chips {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.as-chips li {
  padding: 7px 12px;
  border-radius: 999px;
  font-size: .84rem;
  font-weight: 600;
  color: var(--ink);
  background: color-mix(in srgb, var(--ac) 9%, white);
  border: 1px solid color-mix(in srgb, var(--ac) 22%, white);
  animation: chip-pop .45s cubic-bezier(.34, 1.6, .64, 1) both;
  animation-delay: calc(var(--i) * 40ms);
}
@keyframes chip-pop {
  from {
    opacity: 0;
    transform: translateY(8px) scale(.85);
  }
}
.as-links {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
}
@media (max-width: 900px) {
  .atlas {
    grid-template-columns: 1fr;
  }
  .as-tabs {
    grid-template-columns: repeat(10, 1fr);
  }
}
@media (max-width: 480px) {
  .as-tabs {
    grid-template-columns: repeat(5, 1fr);
  }
  .awc-ic {
    width: 46px;
    height: 46px;
    border-radius: 14px;
  }
  .aw-center small {
    font-size: .72rem;
  }
}
.s-lift {
  background:
    linear-gradient(
      180deg,
      var(--bg),
      #eef1ff 60%,
      var(--bg));
}
.hlift {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, .8fr);
  gap: clamp(20px, 3vw, 44px);
  align-items: center;
}
.hl-scene {
  position: relative;
}
.hl-svg {
  width: 100%;
  height: auto;
  overflow: visible;
}
.hl-ground {
  fill: #e9ecfa;
}
.hl-road {
  fill: #d4d8ea;
}
.hl-lane {
  fill: #fff;
}
.hl-shadow {
  fill: rgba(27, 16, 53, .1);
}
.hl-floor {
  transition: transform .5s cubic-bezier(.34, 1.4, .64, 1);
}
.hf-r {
  fill: #e3e7f5;
}
.hf-l {
  fill: #fbfbfe;
}
.hf-band {
  fill: var(--c);
  opacity: .85;
}
.hf-band.r {
  filter: brightness(.82);
}
.hf-win {
  fill: #c9d2f3;
  transition: fill .4s;
}
.hf-win.r {
  fill: #b8c2ea;
}
.hl-floor.on {
  transform: translate(-7px, 4px);
}
.hl-floor.on .hf-l {
  fill: color-mix(in srgb, var(--c) 16%, white);
}
.hl-floor.on .hf-r {
  fill: color-mix(in srgb, var(--c) 30%, #e3e7f5);
}
.hl-floor.on .hf-win {
  fill: #fde68a;
  animation: win-lit 1.6s ease-in-out infinite;
  animation-delay: calc(var(--k) * 90ms);
}
@keyframes win-lit {
  0%, 100% {
    fill: #fde68a;
  }
  50% {
    fill: #fff7d1;
  }
}
.hl-roof {
  fill: #d6dbef;
}
.hl-sign {
  animation: float-y 3s ease-in-out infinite;
}
.hl-shaft {
  fill: url(#hl-glass);
  stroke: #a5b4fc;
  stroke-width: 1;
}
.hl-shaft.r {
  fill: rgba(199, 210, 254, .35);
}
.hl-car {
  transition: transform 1s cubic-bezier(.65, 0, .35, 1);
}
.hc-f {
  fill: var(--c);
  transition: fill .5s;
}
.hc-s {
  fill: color-mix(in srgb, var(--c) 60%, white);
}
.hc-dot {
  fill: #fff;
  animation: live-ping-s 1s ease-in-out infinite;
}
@keyframes live-ping-s {
  50% {
    opacity: .3;
  }
}
.hl-pin {
  cursor: pointer;
}
.hl-pin rect {
  fill: #fff;
  stroke: var(--c);
  stroke-width: 1.5;
  transition: fill .3s;
}
.hl-pin text {
  fill: var(--c);
  font: 800 10px var(--font-head);
}
.hl-pin.on rect {
  fill: var(--c);
}
.hl-pin.on text {
  fill: #fff;
}
.hl-pin:hover rect {
  fill: color-mix(in srgb, var(--c) 18%, white);
}
.hl-amb {
  animation: amb-drive 9s linear infinite;
}
@keyframes amb-drive {
  0% {
    transform: translate(-130px, -75px);
    opacity: 0;
  }
  6% {
    opacity: 1;
  }
  90% {
    opacity: 1;
  }
  100% {
    transform: translate(165px, 95px);
    opacity: 0;
  }
}
.hl-siren {
  animation: siren .5s steps(1) infinite;
}
@keyframes siren {
  0% {
    fill: #ef2d56;
  }
  50% {
    fill: #2457f5;
  }
}
.hl-house {
  cursor: pointer;
}
.hh-r {
  fill: #ffd9bd;
}
.hh-l {
  fill: #ffedde;
}
.hh-roof {
  fill: #ff7a1a;
}
.hh-roof.r {
  fill: #e05d0b;
}
.hh-door {
  fill: #b45309;
}
.hh-win {
  fill: #fde68a;
}
.hh-heart path {
  fill: #ef2d56;
  transform: scale(.9);
}
.hh-heart {
  animation: float-y 2.6s ease-in-out infinite;
}
.hl-house.on {
  filter: drop-shadow(0 0 10px rgba(255, 122, 26, .6));
}
.hl-side {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.hl-panel {
  display: grid;
  gap: 12px;
  padding: 16px;
  border-radius: 24px;
  background:
    linear-gradient(
      160deg,
      #2a1a52,
      #1b1035);
  box-shadow: var(--shadow-lg), inset 0 1px 0 rgba(255, 255, 255, .1);
}
.hp-head {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #c9c3ec;
  font-size: .8rem;
  font-weight: 700;
}
.hp-btns {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 8px;
}
.hp-btns button {
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font: 800 .9rem var(--font-head);
  color: #e7e3ff;
  background:
    radial-gradient(
      circle at 35% 30%,
      #4a3a86,
      #2a1f56);
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, .12), 0 4px 0 #120a28;
  transition: all .25s;
}
.hp-btns button:hover {
  box-shadow: inset 0 0 0 2px var(--c), 0 4px 0 #120a28;
}
.hp-btns button.on {
  color: #fff;
  background:
    radial-gradient(
      circle at 35% 30%,
      color-mix(in srgb, var(--c) 70%, white),
      var(--c));
  box-shadow:
    0 0 0 3px rgba(255, 255, 255, .15),
    0 0 18px var(--c),
    0 2px 0 #120a28;
  transform: translateY(2px);
}
.hp-display {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: 12px;
  background: #0b0620;
  color: #9b93c9;
  font-size: .82rem;
  font-weight: 600;
}
.hp-display i {
  font-style: normal;
  min-width: 34px;
  text-align: center;
  font: 800 1.4rem var(--font-head);
  color: var(--c);
  text-shadow: 0 0 10px var(--c);
}
.hl-card {
  position: relative;
  padding: 22px;
  border-radius: 24px;
  background: #fff;
  box-shadow: var(--shadow-lg);
  border-left: 6px solid var(--c);
  animation: rh-in .45s var(--ease);
}
.hcard-ic {
  width: 50px;
  height: 50px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  color: #fff;
  background:
    linear-gradient(
      135deg,
      var(--c),
      color-mix(in srgb, var(--c) 55%, #1b1035));
  box-shadow: 0 12px 22px -10px var(--c);
  margin-bottom: 10px;
}
.hl-card h3 {
  font-size: 1.25rem;
  margin: 0;
}
.hcard-meta {
  font-weight: 700;
  color: var(--c);
  font-size: .9rem;
  margin: 2px 0 12px;
  text-align: left !important;
}
.hcard-roles {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 14px;
}
.hcard-roles li {
  padding: 6px 11px;
  border-radius: 999px;
  font-size: .8rem;
  font-weight: 600;
  color: var(--ink);
  background: #f4f3fa;
  animation: chip-pop .4s cubic-bezier(.34, 1.6, .64, 1) both;
  animation-delay: calc(var(--i) * 35ms);
}
.hcard-roles li.core {
  color: #fff;
  background: var(--c);
}
@media (max-width: 960px) {
  .hlift {
    grid-template-columns: 1fr;
  }
  .hl-scene {
    max-width: 560px;
    margin: 0 auto;
    width: 100%;
  }
}
@media (max-width: 420px) {
  .hp-btns {
    grid-template-columns: repeat(6, 1fr);
    gap: 6px;
  }
}
.s-metro {
  background:
    linear-gradient(
      180deg,
      var(--bg),
      #effbf7);
}
.metro {
  position: relative;
  padding-top: 10px;
}
.mt-line {
  position: absolute;
  left: 12.5%;
  right: 12.5%;
  top: 34px;
  height: 12px;
}
.mt-track {
  position: absolute;
  inset: 0;
  border-radius: 12px;
  background:
    linear-gradient(
      90deg,
      #3d5afe,
      #14b8a6 33%,
      #f59e0b 66%,
      #e8344e);
  box-shadow: 0 8px 18px -8px rgba(27, 16, 53, .35);
  overflow: hidden;
}
.mt-track i {
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      90deg,
      rgba(255, 255, 255, .55) 0 10px,
      transparent 10px 26px);
  animation: track-run 1.2s linear infinite;
}
@keyframes track-run {
  to {
    background-position: 26px 0;
  }
}
.mt-train {
  position: absolute;
  z-index: 3;
  top: 50%;
  left: 0;
  translate: -50% -50%;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 10px;
  border-radius: 14px 22px 22px 14px;
  background:
    linear-gradient(
      120deg,
      #1b1035,
      #3b1d78);
  box-shadow: 0 10px 20px -8px rgba(27, 16, 53, .6), inset 0 0 0 2px rgba(255, 255, 255, .15);
  animation: train-go 12s cubic-bezier(.6, 0, .3, 1) infinite;
}
.mtt-win {
  width: 12px;
  height: 10px;
  border-radius: 3px;
  background: #a5f3fc;
}
.mtt-logo {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  background: #ef2d56;
}
@keyframes train-go {
  0%, 8% {
    left: 0%;
  }
  25%, 33% {
    left: 33.333%;
  }
  50%, 58% {
    left: 66.666%;
  }
  75%, 94% {
    left: 100%;
    opacity: 1;
  }
  99% {
    left: 100%;
    opacity: 0;
  }
  100% {
    left: 0%;
    opacity: 0;
  }
}
.mt-coin {
  position: absolute;
  right: 0;
  top: -40px;
  translate: 50% 0;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font: 800 1rem var(--font-head);
  color: #92400e;
  background:
    radial-gradient(
      circle at 35% 30%,
      #fff7c2,
      #fcd34d 45%,
      #d97706);
  box-shadow: 0 4px 0 #b45309;
  opacity: 0;
  animation: mt-coin 12s ease-out infinite;
}
@keyframes mt-coin {
  0%, 74% {
    opacity: 0;
    transform: translateY(20px) scale(.4);
  }
  80% {
    opacity: 1;
    transform: translateY(-6px) scale(1.15) rotateY(360deg);
  }
  92% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  100% {
    opacity: 0;
  }
}
.mt-stations {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
  position: relative;
}
.mt-stations li {
  display: grid;
  justify-items: center;
  gap: 18px;
  text-align: center;
}
.mt-stop {
  position: relative;
  z-index: 2;
  width: 58px;
  height: 58px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--c);
  background: #fff;
  border: 5px solid var(--c);
  box-shadow: 0 10px 20px -10px var(--c);
  animation: stop-arrive 12s ease-in-out infinite;
  animation-delay: calc(var(--k) * 3s);
}
@keyframes stop-arrive {
  0% {
    transform: scale(1);
  }
  4% {
    transform: scale(1.22);
    background: var(--c);
    color: #fff;
    box-shadow: 0 0 0 10px color-mix(in srgb, var(--c) 18%, transparent);
  }
  16% {
    transform: scale(1.08);
    background: var(--c);
    color: #fff;
  }
  24%, 100% {
    transform: scale(1);
    background: #fff;
    color: var(--c);
    box-shadow: 0 10px 20px -10px var(--c);
  }
}
.mt-card {
  display: grid;
  gap: 4px;
  padding: 18px 16px;
  border-radius: 20px;
  background: #fff;
  box-shadow: var(--shadow);
  border-bottom: 4px solid var(--c);
  width: 100%;
  animation: card-arrive 12s ease-in-out infinite;
  animation-delay: calc(var(--k) * 3s);
}
@keyframes card-arrive {
  0% {
    transform: none;
  }
  5%, 18% {
    transform: translateY(-8px);
    box-shadow: 0 24px 40px -22px var(--c);
  }
  26%, 100% {
    transform: none;
  }
}
.mt-card small {
  font-weight: 800;
  font-size: .72rem;
  color: var(--c);
}
.mt-card b {
  font-family: var(--font-head);
  font-size: 1.1rem;
  color: var(--ink);
}
.mt-card > span {
  font-size: .86rem;
  color: var(--muted);
  line-height: 1.5;
  text-align: center;
}
@media (max-width: 760px) {
  .mt-line {
    display: none;
  }
  .mt-stations {
    grid-template-columns: 1fr;
    gap: 14px;
  }
  .mt-stations::before {
    content: "";
