  display: grid;
  place-items: center;
}
.am-gear {
  position: absolute;
  border-radius: 50%;
  background:
    repeating-conic-gradient(
      from 0deg,
      #2a1a52 0 14deg,
      transparent 14deg 30deg);
  mask:
    radial-gradient(
      circle,
      transparent 46%,
      #000 47%,
      #000 64%,
      transparent 65%);
}
.am-gear.g1 {
  inset: 0;
  animation: fr-spin 8s linear infinite;
}
.am-gear.g2 {
  inset: 18%;
  animation: fr-spin 5s linear infinite reverse;
  background:
    repeating-conic-gradient(
      from 0deg,
      #00a88a 0 16deg,
      transparent 16deg 32deg);
}
.am-core {
  position: relative;
  z-index: 2;
  width: 46%;
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  background:
    linear-gradient(
      135deg,
      #00b386,
      #12c2e9);
  box-shadow: 0 0 0 6px rgba(0, 179, 134, .15), 0 14px 28px -10px #00b386;
  transition: transform .4s;
}
.ph-1 .am-core {
  animation: core-shake .3s linear infinite;
}
@keyframes core-shake {
  0%, 100% {
    transform: rotate(0);
  }
  25% {
    transform: rotate(-6deg);
  }
  75% {
    transform: rotate(6deg);
  }
}
.ph-2 .am-core {
  transform: scale(1.1);
  box-shadow: 0 0 0 12px rgba(0, 179, 134, .18), 0 0 40px #12c2e9;
}
.am-beam {
  position: absolute;
  left: -40%;
  right: -40%;
  top: 50%;
  height: 3px;
  translate: 0 -50%;
  background:
    linear-gradient(
      90deg,
      transparent,
      #12c2e9,
      #00b386,
      #12c2e9,
      transparent);
  opacity: .35;
}
.ph-1 .am-beam {
  opacity: 1;
  animation: beam 0.5s linear infinite;
}
@keyframes beam {
  50% {
    opacity: .4;
  }
}
.am-bit {
  position: absolute;
  z-index: 3;
  left: -36%;
  top: 50%;
  width: 8px;
  height: 8px;
  margin-top: -4px;
  border-radius: 2px;
  background: #ef2d56;
  opacity: 0;
}
.ph-1 .am-bit {
  animation: bit-through 1.2s linear infinite;
  animation-delay: calc(var(--k) * .2s);
}
@keyframes bit-through {
  0% {
    opacity: 1;
    transform: translateX(0);
    background: #ef2d56;
  }
  45% {
    transform: translateX(calc(clamp(130px, 16vw, 180px) * .7));
    background: #ef2d56;
  }
  55% {
    background: #00b386;
    border-radius: 50%;
  }
  100% {
    opacity: 1;
    transform: translateX(calc(clamp(130px, 16vw, 180px) * 1.6));
    background: #00b386;
    border-radius: 50%;
  }
}
.am-lbl {
  position: absolute;
  bottom: -26px;
  left: 50%;
  translate: -50% 0;
  padding: 3px 10px;
  border-radius: 999px;
