}
.an-id b {
  font-family:
    ui-monospace,
    Menlo,
    monospace;
  color: var(--ink);
  padding: 2px 8px;
  border-radius: 6px;
  background: #ecfdf5;
}
.an-donut {
  width: 140px;
}
.an-donut circle {
  fill: none;
  stroke-width: 14;
  transform: rotate(-90deg);
  transform-origin: 60px 60px;
}
.d-bg {
  stroke: #eef0f8;
}
.d-a {
  stroke: #00b386;
  stroke-dasharray: 62 100;
  stroke-linecap: round;
  animation: donut-a 7.2s ease-out infinite;
}
.d-b {
  stroke: #8a4dff;
  stroke-dasharray: 28 100;
  stroke-dashoffset: -64;
  stroke-linecap: round;
  animation: donut-b 7.2s ease-out infinite;
}
@keyframes donut-a {
  0% {
    stroke-dasharray: 0 100;
  }
  30%, 100% {
    stroke-dasharray: 62 100;
  }
}
@keyframes donut-b {
  0%, 15% {
    stroke-dasharray: 0 100;
  }
  45%, 100% {
    stroke-dasharray: 28 100;
  }
}
.an-donut text {
  font: 800 16px var(--font-head);
  fill: var(--ink);
}
.an-donut .d-sm {
  font: 600 9px var(--font-body);
  fill: var(--muted);
}
.an-legend {
  display: flex;
