  color: var(--muted);
}
.an-legend i {
  width: 10px;
  height: 10px;
  border-radius: 3px;
}
.an-legend .la {
  background: #00b386;
}
.an-legend .lb {
  background: #8a4dff;
  margin-left: 6px;
}
.an-out small {
  color: var(--muted);
  font-size: .76rem;
}
.anon-promises {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
.anon-promises li {
  position: relative;
  display: grid;
  gap: 4px;
  padding: 18px 16px 16px;
  border-radius: 20px;
  background: #fff;
  box-shadow: var(--shadow);
  overflow: hidden;
}
.anon-promises li::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 4px;
  background: var(--c);
}
.ap-ic {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--c);
  background: color-mix(in srgb, var(--c) 12%, white);
  box-shadow: 0 0 0 0 color-mix(in srgb, var(--c) 30%, transparent);
  animation: ap-ring 3.2s ease-out infinite;
  animation-delay: calc(var(--k) * .8s);
  margin-bottom: 6px;
}
@keyframes ap-ring {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--c) 35%, transparent);
  }
  70%, 100% {
    box-shadow: 0 0 0 12px transparent;
  }
}
.anon-promises b {
  color: var(--ink);
}
.anon-promises small {
  color: var(--muted);
