}
@media (max-width: 900px) {
  .anon-promises {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 760px) {
  .anon-scene {
    grid-template-columns: 1fr;
    justify-items: center;
  }
  .an-card {
    width: 100%;
    max-width: 420px;
  }
  .am-beam {
    left: 50%;
    right: auto;
    top: -40%;
    bottom: -40%;
    width: 3px;
    height: auto;
    translate: -50% 0;
    background:
      linear-gradient(
        180deg,
        transparent,
        #12c2e9,
        #00b386,
        #12c2e9,
        transparent);
  }
  .am-bit {
    display: none;
  }
}
@media (max-width: 480px) {
  .anon-promises {
    grid-template-columns: 1fr;
  }
}
.nav-dd {
  position: relative;
