  width: min(100%, 500px);
  aspect-ratio: 1;
  margin: 0 auto;
  container-type: inline-size;
  perspective: 1200px;
}
.cred-stack {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
}
.cred {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 60cqw;
  aspect-ratio: 1.5;
  padding: 4cqw;
  border-radius: 5cqw;
  background: #fff;
  box-shadow: 0 30px 60px -24px rgba(27, 16, 53, .45), inset 0 0 0 1px rgba(27, 16, 53, .06);
  display: grid;
  align-content: start;
  gap: 1cqw;
  animation: shuffle 9s cubic-bezier(.6, 0, .3, 1) infinite;
}
.cred.c2 {
  animation-delay: -6s;
  background:
    linear-gradient(
      150deg,
      #1b1035,
      #2e1a5c);
  color: #fff;
}
.cred.c3 {
  animation-delay: -3s;
  background:
    linear-gradient(
      150deg,
      #fff,
      var(--gs));
}
@keyframes shuffle {
  0%, 28% {
    transform: translate(-50%, -50%) translateZ(60px) rotateY(-12deg) rotate(-2deg);
    z-index: 3;
  }
  33%, 61% {
    transform: translate(-8%, -62%) translateZ(-20px) rotateY(-26deg) rotate(9deg) scale(.86);
    z-index: 2;
  }
  66%, 94% {
    transform: translate(-92%, -38%) translateZ(-40px) rotateY(12deg) rotate(-10deg) scale(.86);
    z-index: 1;
  }
  100% {
    transform: translate(-50%, -50%) translateZ(60px) rotateY(-12deg) rotate(-2deg);
    z-index: 3;
  }
}
.cr-top {
