  color: #fff;
  background:
    conic-gradient(
      from 0deg,
      #ffb020,
      #ff6a2c,
      #ffb020);
  box-shadow: 0 0 0 1.4cqw #fff3d6;
  animation: fr-spin 12s linear infinite;
}
.cr-seal svg {
