  left: 50%;
  top: 50%;
  padding: 5px 11px;
  border-radius: 999px;
  background: #fff;
  box-shadow: var(--shadow);
  font-weight: 700;
  font-size: clamp(.56rem, 2.4cqw, .76rem);
  color: var(--g1);
  white-space: nowrap;
  transform: translate(-50%, -50%) rotate(calc(var(--i) * 51.4deg)) translateX(46cqw) rotate(calc(var(--i) * -51.4deg));
  animation: chip-orbit 40s linear infinite;
  animation-delay: calc(var(--i) * -5.7s);
}
@keyframes chip-orbit {
  from {
    transform: translate(-50%, -50%) rotate(0deg) translateX(46cqw) rotate(0deg);
  }
  to {
    transform: translate(-50%, -50%) rotate(360deg) translateX(46cqw) rotate(-360deg);
  }
