@media (max-width: 560px) {
  .l4-postmark {
    display: none;
  }
  .ct-fx {
    left: 62px;
  }
}
.conv {
  position: relative;
  width: min(100%, 520px);
  aspect-ratio: 1.1;
  margin: 0 auto;
  container-type: inline-size;
}
.cv-belt {
  position: absolute;
  left: 0;
  right: 22%;
  bottom: 26%;
  height: 14cqw;
}
.cvb-top {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 5cqw;
  border-radius: 3cqw;
  background:
    repeating-linear-gradient(
      90deg,
      #2a1f56 0 6cqw,
      #3b2f72 6cqw 12cqw);
  box-shadow: 0 10px 20px -10px rgba(27, 16, 53, .6);
  animation: belt 1.2s linear infinite;
}
@keyframes belt {
  to {
    background-position: 12cqw 0;
  }
}
.cvb-rollers {
  position: absolute;
  left: 2%;
  right: 2%;
  top: 5cqw;
  display: flex;
  justify-content: space-between;
}
.cvb-rollers i {
  width: 4.4cqw;
  height: 4.4cqw;
  border-radius: 50%;
  background:
    conic-gradient(
      #94a3b8 0 25%,
      #cbd5e1 0 50%,
      #94a3b8 0 75%,
      #cbd5e1 0);
  animation: fr-spin 1s linear infinite;
}
.cv-box {
  position: absolute;
  left: -16cqw;
  bottom: 5cqw;
  width: 15cqw;
  height: 13cqw;
  animation: box-ride 8s linear infinite;
  animation-delay: calc(var(--i) * -2s);
}
.cvx-face {
  position: absolute;
  inset: 0;
  border-radius: 2cqw;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
  color: #fff;
  background:
    linear-gradient(
      135deg,
      var(--bx1, #3d5afe),
      var(--bx2, #6366f1));
  box-shadow: 0 10px 18px -10px rgba(27, 16, 53, .6), inset 0 -1.6cqw 0 rgba(0, 0, 0, .15);
}
.cvx-face b {
  font-size: clamp(.5rem, 2.4cqw, .76rem);
  font-weight: 800;
}
.cv-box:nth-child(4) {
  --bx1: #14b8a6;
  --bx2: #0ea5e9;
}
.cv-box:nth-child(5) {
  --bx1: #f59e0b;
  --bx2: #ff6a2c;
}
.cv-box:nth-child(6) {
  --bx1: #ef2d56;
  --bx2: #8a4dff;
}
@keyframes box-ride {
  0% {
    transform: translateX(0);
    opacity: 0;
  }
  5% {
    opacity: 1;
  }
  78% {
    transform: translateX(78cqw);
    opacity: 1;
  }
  84% {
    transform: translateX(84cqw) scale(.6);
    opacity: 0;
  }
  100% {
    transform: translateX(84cqw) scale(.6);
    opacity: 0;
  }
}
.cv-press {
  position: absolute;
  right: 4%;
  bottom: 26%;
  width: 26cqw;
  height: 44cqw;
  border-radius: 4cqw 4cqw 2cqw 2cqw;
  background:
    linear-gradient(
      160deg,
      #2e1a5c,
      #1b1035);
  box-shadow: var(--shadow-lg), inset 0 0 0 1px rgba(255, 255, 255, .08);
}
.cvp-head {
  position: absolute;
  left: 0;
  right: 0;
  top: 3cqw;
  display: grid;
  justify-items: center;
  gap: 2px;
  color: #fde68a;
  font-weight: 800;
  font-size: clamp(.5rem, 2.2cqw, .72rem);
  text-align: center;
}
.cvp-ram {
  position: absolute;
  left: 20%;
  right: 20%;
  top: 14cqw;
  height: 16cqw;
  border-radius: 1.6cqw;
  background:
    linear-gradient(
      180deg,
      #94a3b8,
      #e2e8f0);
  box-shadow: inset 0 -2cqw 0 rgba(0, 0, 0, .15);
  animation: ram 2s cubic-bezier(.6, 0, .3, 1) infinite;
}
@keyframes ram {
  0%, 55%, 100% {
    transform: translateY(0);
  }
  65% {
    transform: translateY(10cqw);
  }
  75% {
    transform: translateY(0);
  }
}
.cvp-light {
  position: absolute;
  left: 50%;
  top: 34cqw;
  width: 4cqw;
  height: 4cqw;
  margin-left: -2cqw;
  border-radius: 50%;
  background: #34f5c5;
  box-shadow: 0 0 12px #34f5c5;
  animation: live-ping-s 1s ease-in-out infinite;
}
.cv-coin {
  position: absolute;
  z-index: 3;
  right: 13%;
  bottom: 72%;
  width: 12cqw;
  height: 12cqw;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background:
    radial-gradient(
      circle at 35% 30%,
      #fff7c2,
      #fcd34d 45%,
      #d97706);
  box-shadow: 0 1cqw 0 #b45309;
  animation: coin-hop 2s cubic-bezier(.4, 0, .4, 1) infinite;
}
.cv-coin b {
  font: 800 5cqw var(--font-head);
  color: #92400e;
}
@keyframes coin-hop {
  0%, 60% {
    opacity: 0;
    transform: translate(0, 10cqw) scale(.4);
  }
  70% {
    opacity: 1;
    transform: translate(0, -4cqw) scale(1) rotateY(180deg);
  }
  90% {
    opacity: 1;
    transform: translate(-6cqw, 40cqw) scale(.8) rotateY(360deg);
  }
  100% {
    opacity: 0;
    transform: translate(-6cqw, 46cqw) scale(.6);
  }
}
.cv-wallet {
  position: absolute;
  right: 18%;
  bottom: 2%;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 16px;
  border-radius: 16px;
  color: #fff;
  font-weight: 800;
  background:
    linear-gradient(
      135deg,
      #14b8a6,
      #3d5afe);
  box-shadow: 0 16px 30px -14px #14b8a6;
  animation: wallet-pulse 2s ease-in-out infinite;
}
@keyframes wallet-pulse {
  0%, 85% {
    transform: scale(1);
  }
  92% {
    transform: scale(1.1);
  }
  100% {
    transform: scale(1);
  }
}
.cv-wallet small {
  font-size: .8rem;
}
.cv-spark {
  position: absolute;
  width: 10px;
  height: 10px;
  background: #ffb020;
  clip-path: polygon(50% 0, 62% 38%, 100% 50%, 62% 62%, 50% 100%, 38% 62%, 0 50%, 38% 38%);
  animation: twinkle 2.4s ease-in-out infinite;
}
.cv-spark.s1 {
  right: 6%;
  top: 8%;
}
.cv-spark.s2 {
  right: 34%;
  top: 20%;
  animation-delay: .8s;
}
.cv-spark.s3 {
  left: 12%;
  top: 26%;
  animation-delay: 1.6s;
}
.loop {
  display: grid;
  grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
  gap: clamp(20px, 4vw, 56px);
  align-items: center;
}
.lp-track {
  position: relative;
  width: min(100%, 440px);
  aspect-ratio: 1;
  margin: 0 auto;
}
.lp-track svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}
.lp-road {
  fill: none;
  stroke: #e6e4f3;
  stroke-width: 34;
}
.lp-lane {
  fill: none;
  stroke-width: 6;
  stroke-linecap: round;
}
.lp-dash {
  fill: none;
  stroke: #fff;
  stroke-width: 2;
  stroke-dasharray: 8 10;
  animation: lp-dash 2s linear infinite;
}
@keyframes lp-dash {
  to {
    stroke-dashoffset: -36;
  }
}
.lp-check {
  fill: #fff;
  stroke: var(--c);
  stroke-width: 6;
  animation: lp-hit 8s ease-in-out infinite;
  animation-delay: calc(var(--i) * 2s);
  transform-box: fill-box;
  transform-origin: center;
}
@keyframes lp-hit {
  0%, 2% {
    fill: var(--c);
    transform: scale(1.35);
  }
  12%, 100% {
    fill: #fff;
    transform: scale(1);
  }
}
.lp-token {
  offset-path: path("M150 32 A118 118 0 1 1 149.9 32");
  offset-rotate: 0deg;
  animation: lap 8s linear infinite;
}
.lp-token circle {
  fill: #ff6a2c;
  filter: drop-shadow(0 0 8px #ff6a2c);
}
.lp-token .lp-halo {
  fill: rgba(255, 106, 44, .2);
  filter: none;
}
@keyframes lap {
  from {
    offset-distance: 0%;
  }
  to {
    offset-distance: 100%;
  }
}
.lp-center {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 2px;
  text-align: center;
  color: var(--ink);
}
.lp-center svg {
  color: #ff6a2c;
  animation: fr-spin 8s linear infinite;
}
.lp-center b {
  font: 800 1.4rem var(--font-head);
}
.lp-center small {
  color: var(--muted);
  font-size: .8rem;
}
.lp-steps {
  list-style: none;
  display: grid;
  gap: 12px;
}
.lp-steps li {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  padding: 16px 18px;
  border-radius: 20px;
  background: #fff;
  box-shadow: var(--shadow);
  border-left: 5px solid var(--c);
  animation: lp-card 8s ease-in-out infinite;
  animation-delay: calc(var(--i) * 2s);
}
@keyframes lp-card {
  0%, 2% {
    transform: translateX(10px);
    box-shadow: 0 20px 40px -22px var(--c);
  }
  22%, 100% {
    transform: none;
    box-shadow: var(--shadow);
  }
}
.lps-ic {
  width: 44px;
  height: 44px;
  flex: none;
  border-radius: 14px;
  display: grid;
  place-items: center;
  color: #fff;
  background: var(--c);
}
.lp-steps small {
  display: block;
  font-weight: 800;
  font-size: .72rem;
  color: var(--c);
}
.lp-steps b {
  display: block;
  color: var(--ink);
  font-size: 1.05rem;
}
.lp-steps li span span {
  display: block;
  font-size: .88rem;
  color: var(--muted);
  line-height: 1.5;
}
@media (max-width: 900px) {
  .loop {
    grid-template-columns: 1fr;
  }
  .lp-track {
    max-width: 320px;
  }
}
.dial {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 28px;
  align-items: center;
}
.dl-face {
  position: relative;
  width: clamp(200px, 26vw, 280px);
  aspect-ratio: 1;
}
.dl-face svg {
  width: 100%;
  height: 100%;
}
.dl-ring {
  fill: rgba(255, 255, 255, .05);
  stroke: rgba(255, 255, 255, .15);
  stroke-width: 2;
}
.dl-sun {
  fill: none;
  stroke: #facc15;
  stroke-width: 6;
  stroke-linecap: round;
  opacity: .55;
}
.dl-night {
  fill: none;
  stroke: #8a4dff;
  stroke-width: 6;
  stroke-linecap: round;
  opacity: .6;
}
.dl-tick {
  stroke: rgba(255, 255, 255, .35);
  stroke-width: 2;
}
.dl-num {
  fill: rgba(255, 255, 255, .6);
  font: 700 12px var(--font-head);
}
.dl-dot {
  fill: rgba(255, 255, 255, .3);
  stroke: #1b1035;
  stroke-width: 3;
  transition: r .3s;
}
.dl-dot.past {
  fill: #34f5c5;
}
.dl-dot.on {
  fill: #facc15;
  filter: drop-shadow(0 0 8px #facc15);
}
.dl-hand {
  transform-origin: 130px 130px;
  transition: transform .9s cubic-bezier(.34, 1.4, .64, 1);
}
.dl-hand line {
  stroke: #facc15;
  stroke-width: 4;
  stroke-linecap: round;
}
.dl-hand circle {
  fill: #facc15;
}
.dl-icon {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% 30px;
  width: 46px;
  height: 46px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  color: #1b1035;
  background: #facc15;
  box-shadow: 0 10px 22px -8px #facc15;
  animation: stamp-in .5s cubic-bezier(.34, 1.8, .64, 1);
}
.dl-list ol {
  list-style: none;
  display: grid;
  gap: 8px;
  margin-bottom: 16px;
}
.dl-list ol button {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  border-radius: 16px;
  text-align: left;
  color: rgba(255, 255, 255, .7);
  background: rgba(255, 255, 255, .05);
  border: 1px solid rgba(255, 255, 255, .08);
  transition: all .3s;
}
.dlt-time {
  flex: none;
  min-width: 54px;
  padding: 4px 8px;
  border-radius: 8px;
  text-align: center;
  font: 800 .8rem var(--font-head);
  color: #facc15;
  background: rgba(250, 204, 21, .12);
}
.dlt-txt b {
  display: block;
  color: #fff;
}
.dlt-txt small {
  font-size: .82rem;
}
.dl-list li.on button {
  background: rgba(250, 204, 21, .14);
  border-color: #facc15;
  transform: translateX(6px);
}
.dl-list li.past button {
  opacity: .7;
}
@media (max-width: 760px) {
  .dial {
    grid-template-columns: 1fr;
    justify-items: center;
  }
  .dl-list {
    width: 100%;
  }
}
.towers {
  display: grid;
  gap: 14px;
  padding: 22px;
  border-radius: 30px;
  background: #fff;
  box-shadow: var(--shadow-lg);
}
.tw-cols {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 10px;
  align-items: end;
  min-height: 300px;
}
.tw-col {
  display: grid;
  justify-items: center;
  gap: 4px;
  text-align: center;
}
.tw-stack {
  position: relative;
  display: flex;
  flex-direction: column-reverse;
  align-items: center;
  width: 58px;
  padding-top: 52px;
}
.tw-stack i {
  width: 52px;
  height: 14px;
  margin-top: -6px;
  border-radius: 50%;
  background:
    radial-gradient(
      ellipse at 50% 35%,
      #fff6c4,
      #fcd34d 48%,
      #e59e0b);
  box-shadow: 0 4px 0 #c27707;
  opacity: 0;
  transform: translateY(-40px);
}
.tw-stack i:nth-child(odd) {
  translate: 3px 0;
}
.towers.is-in .tw-stack i {
  animation: tw-drop .45s cubic-bezier(.34, 1.5, .64, 1) forwards;
  animation-delay: calc(var(--i) * 120ms + var(--k) * 70ms);
}
@keyframes tw-drop {
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tw-av-in {
  from {
    opacity: 0;
    transform: translateY(-10px) scale(.6);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tw-av {
  position: absolute;
  top: 0;
  left: 50%;
  translate: -50% 0;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 0 0 3px #fff, 0 0 0 5px var(--c);
  opacity: 0;
}
.towers.is-in .tw-av {
  animation: tw-av-in .5s cubic-bezier(.34, 1.8, .64, 1) forwards;
  animation-delay: calc(var(--i) * 120ms + var(--n) * 70ms);
}
.tw-col b {
  font-size: .8rem;
  color: var(--ink);
  line-height: 1.2;
  margin-top: 8px;
}
.tw-col small {
  font-size: .68rem;
  color: var(--muted);
  line-height: 1.3;
}
.tw-col {
  border-bottom: 4px solid var(--c);
  padding-bottom: 10px;
}
.tw-key {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: .78rem;
  color: var(--muted);
  margin: 0;
}
.tw-key span:first-child {
  font-weight: 700;
  color: var(--ink);
}
.tw-key i {
  flex: 1;
  height: 4px;
  border-radius: 4px;
  background:
    linear-gradient(
      90deg,
      #fcd34d,
      #e5e7eb);
}
@media (max-width: 640px) {
  .tw-cols {
    grid-template-columns: repeat(3, 1fr);
    row-gap: 22px;
  }
  .tw-col small {
    display: none;
  }
}
.portals {
  display: grid;
  gap: 18px;
}
.pt-doors {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.door {
  position: relative;
  display: grid;
  gap: 6px;
  padding: 150px 20px 20px;
  border-radius: 28px;
  text-decoration: none;
  color: var(--text);
  background: #fff;
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  perspective: 800px;
  transition: transform .4s var(--ease);
}
.door-frame {
  position: absolute;
  left: 50%;
  top: 16px;
  translate: -50% 0;
  width: 96px;
  height: 120px;
  border-radius: 48px 48px 6px 6px;
  background:
    linear-gradient(
      135deg,
      var(--g1),
      var(--g2));
  box-shadow: inset 0 0 0 5px rgba(255, 255, 255, .35);
}
.door-glow {
  position: absolute;
  inset: 10px;
  border-radius: 40px 40px 4px 4px;
  background:
    radial-gradient(
      circle at 50% 70%,
      #fff7c2,
      rgba(255, 255, 255, .2) 60%);
}
.door-leaf {
  position: absolute;
  z-index: 2;
  inset: 6px;
  border-radius: 42px 42px 4px 4px;
  background:
    linear-gradient(
      160deg,
      #fff,
      var(--gs));
  transform-origin: left;
  transition: transform .7s cubic-bezier(.34, 1.2, .64, 1);
  box-shadow: 4px 0 12px -6px rgba(0, 0, 0, .3);
}
.dl-knob {
  position: absolute;
  right: 12px;
  top: 55%;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--g1);
}
.door:hover {
  transform: translateY(-6px);
}
.door:hover .door-leaf,
.door:focus-visible .door-leaf {
  transform: rotateY(-72deg);
}
.door-ic {
  position: absolute;
  z-index: 1;
  left: 50%;
  top: 58px;
  translate: -50% 0;
  color: var(--g1);
  opacity: 0;
  transition: opacity .4s .15s;
}
.door:hover .door-ic {
  opacity: 1;
  animation: float-y 2s ease-in-out infinite;
}
.door b {
  font-family: var(--font-head);
  font-size: 1.2rem;
  color: var(--ink);
  text-align: center;
}
.door small {
  font-size: .86rem;
  color: var(--muted);
  text-align: center;
  line-height: 1.45;
}
.door-n {
  justify-self: center;
  margin-top: 4px;
  padding: 5px 12px;
  border-radius: 999px;
  font-size: .8rem;
  color: var(--g1);
  background: var(--gs);
  font-weight: 600;
}
.door-n em {
  font-style: normal;
  font-weight: 800;
}
.door-go {
  justify-self: center;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 800;
  color: var(--g1);
  font-size: .9rem;
}
.pt-badges {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}
.pbadge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px 6px 6px;
  border-radius: 999px;
  text-decoration: none;
  color: var(--ink);
  font-weight: 600;
  font-size: .84rem;
  background: #fff;
  box-shadow: 0 8px 18px -14px rgba(27, 16, 53, .5);
  border: 1px solid color-mix(in srgb, var(--c) 25%, white);
  transition: transform .25s, box-shadow .25s;
}
.pbadge > span {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  background: var(--c);
}
.pbadge em {
  font-style: normal;
  font-weight: 800;
  color: var(--c);
  font-size: .76rem;
}
.pbadge:hover {
  transform: translateY(-3px);
  box-shadow: 0 14px 24px -14px var(--c);
}
@media (max-width: 900px) {
  .pt-doors {
    grid-template-columns: 1fr;
  }
  .door {
    padding-top: 150px;
  }
}
.cpulse {
  position: relative;
  display: grid;
  gap: 14px;
  padding: 18px;
  border-radius: 28px;
  background: rgba(255, 255, 255, .05);
  border: 1px solid rgba(255, 255, 255, .1);
}
.cp-ecg {
  width: 100%;
  height: 90px;
}
.cp-ecg path {
  fill: none;
  stroke: #34f5c5;
  stroke-width: 3;
  stroke-linejoin: round;
  stroke-dasharray: 30 70;
  animation: ecg-run 3.6s linear infinite;
  filter: drop-shadow(0 0 6px #34f5c5);
}
.cp-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.cp-grid span {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 14px;
  font-weight: 600;
  font-size: .84rem;
  color: rgba(255, 255, 255, .6);
