}
.vd-slot.on {
  background:
    linear-gradient(
      180deg,
      rgba(255, 255, 255, .04),
      color-mix(in srgb, var(--ic) 45%, transparent));
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--ic) 70%, white), 0 0 22px color-mix(in srgb, var(--ic) 60%, transparent);
}
.vd-item {
