  animation-delay: calc(var(--k) * -.4s);
}
.vd-slot.on .vd-item {
  animation: vd-drop 1.5s cubic-bezier(.5, 0, .7, .4) both;
}
@keyframes vd-bob {
  50% {
    transform: translateY(-3px);
  }
}
@keyframes vd-drop {
  0% {
