  }
  30% {
    transform: translateY(4px) rotate(-6deg);
  }
  45% {
    transform: translateY(2px) rotate(4deg);
  }
  80% {
    transform: translateY(70px) rotate(18deg);
    opacity: 0;
  }
  81% {
    transform: translateY(-30px);
    opacity: 0;
  }
  100% {
    transform: none;
    opacity: 1;
  }
}
.vd-prod {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  color: #fff;
  background:
    linear-gradient(
      145deg,
      color-mix(in srgb, var(--ic, #8a4dff) 65%, white),
      var(--ic, #8a4dff));
  box-shadow:
    0 5px 0 color-mix(in srgb, var(--ic, #8a4dff) 60%, black),
    0 8px 16px rgba(0, 0, 0, .4),
