  background: #ffe066;
}
@keyframes vd-pop {
  0% {
    opacity: 1;
    transform: rotate(calc(var(--p) * 60deg)) translateY(0);
  }
  100% {
    opacity: 0;
    transform: rotate(calc(var(--p) * 60deg)) translateY(-28px);
  }
}
.vd-cta {
  display: flex;
  justify-content: center;
