}
.rr-who small {
  display: block;
  font-size: .76rem;
  color: var(--muted, #5b5675);
}
.rr-track {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 150px;
  align-items: center;
  gap: 10px;
}
.rr-track::before {
  content: "";
  grid-column: 1;
  height: 14px;
  border-radius: 999px;
  background:
    repeating-linear-gradient(
      90deg,
      #efedf6 0 calc(10% - 2px),
      #e3dff0 calc(10% - 2px) 10%);
}
.rr-bar {
  position: absolute;
  left: calc((100% - 160px) * var(--lf));
  width: calc((100% - 160px) * var(--wf));
  top: 50%;
  height: 22px;
  translate: 0 -50%;
  border-radius: 999px;
  background:
    linear-gradient(
      90deg,
      var(--c),
      var(--c2));
  box-shadow: 0 8px 18px -8px var(--c), inset 0 2px 0 rgba(255, 255, 255, .4);
  overflow: hidden;
  transform: scaleX(0);
  transform-origin: 0 50%;
  transition: transform 1.1s cubic-bezier(.2, .8, .2, 1);
  transition-delay: calc(var(--i) * 160ms);
}
.rr-glint {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      100deg,
      transparent 30%,
      rgba(255, 255, 255, .55) 50%,
      transparent 70%);
  background-size: 220% 100%;
  animation: rr-glint 2.6s ease-in-out infinite;
}
@keyframes rr-glint {
  from {
