}
.iv-pocket {
  position: absolute;
  inset: 0;
  z-index: 3;
  border-radius: 14px;
  background:
    linear-gradient(
      165deg,
      var(--c2),
      var(--c));
  clip-path: polygon(0 0, 50% 54%, 100% 0, 100% 100%, 0 100%);
  box-shadow: inset 0 -20px 30px rgba(0, 0, 0, .12);
}
.iv-pocket::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      32deg,
      transparent 49.4%,
      rgba(255, 255, 255, .2) 50%,
      transparent 50.6%),
    linear-gradient(
      -32deg,
      transparent 49.4%,
      rgba(0, 0, 0, .12) 50%,
      transparent 50.6%);
}
.iv-front {
  position: absolute;
  left: 7%;
  bottom: 9%;
  width: 56%;
  z-index: 4;
  display: grid;
  gap: 2px;
  color: #fff;
  pointer-events: none;
}
.ef-to {
  font-size: .66rem;
  font-weight: 700;
  opacity: .85;
}
.ef-title {
  font-size: .95rem;
  font-weight: 800;
  line-height: 1.15;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .15);
}
.ef-lines {
  display: grid;
  gap: 4px;
  margin-top: 4px;
}
.ef-lines i {
  height: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, .4);
  width: 80%;
}
.ef-lines i + i {
  width: 55%;
}
.iv-flap {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 58%;
  z-index: 5;
  border-radius: 14px 14px 0 0;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--c2) 85%, white),
      var(--c2));
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  transform-origin: 50% 0;
  transition: transform .5s cubic-bezier(.4, 0, .2, 1), z-index 0s .25s;
}
.ivl.open .iv-flap {
  transform: rotateX(180deg);
  z-index: 1;
  transition: transform .5s cubic-bezier(.4, 0, .2, 1), z-index 0s .2s;
}
.iv-seal {
  position: absolute;
  left: 50%;
  top: 56%;
  z-index: 7;
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  translate: -50% -50%;
  border-radius: 50%;
  background:
    radial-gradient(
      circle at 35% 30%,
      #fff3b0,
      #fbbf24 48%,
      #d97706 100%);
  box-shadow:
    0 0 0 4px color-mix(in srgb, #fbbf24 40%, transparent),
    0 6px 10px rgba(0, 0, 0, .3),
    inset 0 -3px 0 rgba(0, 0, 0, .15);
  transition:
    left .5s var(--ease),
    top .5s var(--ease),
    transform .5s var(--ease);
  animation: iv-seal 2.8s ease-in-out infinite;
}
.iv-seal b {
  font-size: 1.05rem;
  font-weight: 900;
  color: #6b3b00;
}
@keyframes iv-seal {
  50% {
    box-shadow:
      0 0 0 9px color-mix(in srgb, #fbbf24 0%, transparent),
      0 6px 10px rgba(0, 0, 0, .3),
      inset 0 -3px 0 rgba(0, 0, 0, .15);
  }
}
.ivl.open .iv-seal {
  left: 88%;
  top: 80%;
  transform: scale(.82) rotate(12deg);
}
.iv-stamp {
  position: absolute;
  right: 7%;
  bottom: 14%;
  z-index: 4;
  display: grid;
  place-items: center;
  width: 40px;
  height: 46px;
  color: var(--c);
  background: #fff;
  border-radius: 4px;
  outline: 3px dotted #fff;
  outline-offset: 1px;
  box-shadow: 0 3px 6px rgba(0, 0, 0, .2);
  transform: rotate(6deg);
  transition: opacity .3s;
}
.iv-post {
  position: absolute;
  right: 18%;
  bottom: 8%;
  z-index: 4;
  display: grid;
  place-items: center;
  align-content: center;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, .85);
  color: #fff;
  font-size: .52rem;
  font-weight: 800;
  letter-spacing: .08em;
  line-height: 1;
  transform: rotate(-14deg);
}
.iv-post b {
  font-size: 1.05rem;
  letter-spacing: 0;
}
.ivl.open .iv-stamp,
.ivl.open .iv-post {
  opacity: 0;
}
.iv-new {
  position: absolute;
  left: -6px;
  top: -12px;
  z-index: 8;
  padding: 4px 10px;
  border-radius: 8px;
  color: #fff;
  font-size: .72rem;
  font-weight: 800;
  background: #ef2d56;
  box-shadow: 0 6px 14px -6px #ef2d56;
  animation: iv-new .5s cubic-bezier(.3, 1.6, .5, 1) both;
}
@keyframes iv-new {
  from {
    transform: scale(0) rotate(-20deg);
  }
}
.ivl.arrive .iv-3d {
  animation: iv-arrive .9s cubic-bezier(.3, 1.5, .5, 1);
}
@keyframes iv-arrive {
  0% {
    transform: translateY(-40px) rotate(-8deg) scale(.9);
  }
  40% {
    transform: translateY(0) rotate(4deg);
  }
  60% {
    transform: rotate(-3deg);
  }
  80% {
    transform: rotate(1.5deg);
  }
}
.si-foot {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
  margin-top: 6px;
}
.si-note {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 6px;
  margin: 0;
  font-size: .82rem;
  color: var(--muted, #5b5675);
  text-align: center !important;
}
@media (max-width: 1150px) {
  .si-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 900px) {
  .si-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .rr-ruler {
    margin-left: 10px;
    margin-right: 170px;
  }
  .rr-lane {
    grid-template-columns: 1fr;
    gap: 8px;
  }
}
@media (max-width: 600px) {
  .si-grid {
    grid-template-columns: minmax(0, 360px);
    justify-content: center;
    gap: 96px 0;
    padding-top: 90px;
  }
  .rrail {
    padding: 14px 12px;
  }
  .rr-ruler {
    margin-right: 10px;
  }
  .rr-track {
    grid-template-columns: 1fr;
  }
  .rr-tag {
    grid-column: 1;
    justify-self: start;
    grid-row: 2;
    min-width: 0;
    font-size: 1rem;
  }
  .rr-bar {
    top: 7px;
    left: calc(100% * var(--lf));
    width: calc(100% * var(--wf));
