  .rr-stack {
    left: calc(100% * (var(--lf) + var(--wf)));
    bottom: auto;
    top: 7px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sinbox *,
  .sinbox *::before {
    animation: none !important;
    transition-duration: 0s !important;
    transition-delay: 0s !important;
  }
}
.msg-bot {
